insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('safetystats', 'beginner', 'module', 'm01-a-rate-is-a-count-over-exposure', 1, 'UGHELLI states 9 recordable cases in 2318640 hours for one year. The report you are writing uses the 200,000 hour base. What recordable rate goes in it?', '["3.881586, which is the same 9 cases over the same hours on the IOGP base of 1,000,000 hours.", "0.776317 per 200,000 hours, from 9 x 200,000 / 2318640.", "0.345030 per 200,000 hours, which is what the 4 DART cases give over the same 2318640 hours worked.", "388.158576, the figure the engine returns when the base passed is 100,000,000 hours."]'::jsonb, 1, 'The engine''s formula is count x base / exposureHours, so 9 x 200,000 / 2318640 gives 0.776317. The tempting 3.881586 is the same record on the IOGP base: nothing is wrong with its arithmetic, it answers a different base than the report asked for, and it reads five times larger for that reason alone.'),
  ('safetystats', 'beginner', 'module', 'm01-a-rate-is-a-count-over-exposure', 2, 'Two crews of 40 people each had one recordable apiece. The day crew worked 80000 hours and the rotation crew 116480. What does the engine report for the rotation crew per 200,000 hours?', '["2.500000, the same as the day crew, since both crews have 40 people and one recordable each and so share one rate.", "1.456000, the ratio of the rotation crew''s hours to the day crew''s.", "2.500000 per 100 people, the per head figure for both crews.", "1.717033, because its one case is spread over 116480 hours, which is more exposure than the day crew''s 80000."]'::jsonb, 3, '1 x 200,000 / 116480 is 1.717033. The per head figure of 2.500000 recordables per 100 people is the same for both crews, which is exactly why it hides the difference: the rotation crew was exposed for more hours. 1.456000 is the ratio of the two rates, and the engine has no headcount input at all.'),
  ('safetystats', 'beginner', 'module', 'm01-a-rate-is-a-count-over-exposure', 3, 'The day crew''s rate is 1.456000 times the rotation crew''s rate, although each crew had one recordable and 40 people. Where does that factor come from?', '["It is the rotation crew''s 116480 hours over the day crew''s 80000 hours, because with the count held equal only the exposure can move the rate.", "It is the day crew''s headcount over the rotation crew''s headcount, scaled to the 200,000 hour base.", "It records that the day crew''s recordable was the more serious case of the two.", "It is the ratio of the per head figures, which the engine derives from the hours."]'::jsonb, 0, 'With one case each, the rates stand in the inverse ratio of the hours: 116480 over 80000 is 1.456000, the same as 2.500000 over 1.717033. The headcounts are equal at 40 and the per head figures are equal at 2.500000, so neither can produce the factor, and the engine does not look at how serious a case was.'),
  ('safetystats', 'beginner', 'module', 'm01-a-rate-is-a-count-over-exposure', 4, 'A contractor sends you headcounts and asks why the engine will not take them. What does the engine do with a headcount?', '["It converts each head into a full-time year of 40 h x 50 weeks and uses the product as the exposure hours.", "It accepts headcount on the OSHA base only, since that base is defined as 100 full-time workers.", "Nothing: it has no headcount input at all, and takes the hours worked as the exposure.", "It takes headcount when the hours are blank and flags the rate as an estimate."]'::jsonb, 2, 'The engine takes hours and has no headcount input. A headcount is a snapshot of a list and says nothing about how long anyone worked, so the two crews of 40 would read the same per head and differ per hour. The OSHA label describes an imaginary 100 workers as a reading scale; it is no invitation to pass heads.'),
  ('safetystats', 'beginner', 'module', 'm01-a-rate-is-a-count-over-exposure', 5, 'The rotation crew reads 1.717033 per 200,000 hours. Which reading of that figure is the one the engine''s own base label supports?', '["The crew of 40 had about 1.717033 recordables for every 100 of its own people over the year it worked.", "At this crew''s observed rate, 100 full-time workers on 40 hours for 50 weeks would have about 1.717033 recordables in a year.", "The crew had 1.717033 recordables in its year, spread across the 116480 hours it actually worked.", "At this crew''s rate, 200,000 people would have 1.717033 recordables between them in a year."]'::jsonb, 1, 'The label reads per 200,000 hours (OSHA/BLS: 100 full-time workers, 40 h x 50 weeks), and 100 times 40 times 50 is 200000. It describes an imaginary workforce. The per head reading is the trap: per 100 of its own people the crew reads 2.500000, which is a different figure, because the base has no headcount in it.'),
  ('safetystats', 'beginner', 'module', 'm01-a-rate-is-a-count-over-exposure', 6, 'Your script calls the rate function with a count and hours and forgets the base. What comes back?', '["The rate on the OSHA base of 200,000 hours, which is the engine''s default when no base is named.", "A rate on the IOGP base of 1,000,000 hours, with a note in the basis block saying a default was used.", "An error object whose field is `base`, carrying the engine''s words that there is no default, and no rate.", "An error object whose field is `exposureHours`, since the hours cannot be scaled to anything without a base."]'::jsonb, 2, 'The engine''s own words are: base is required: name the base (200,000 for OSHA/BLS, 1,000,000 for IOGP, 100,000,000 for FAR); there is no default. The tempting answer is a default, and it is the very thing the engine refuses to supply, because the two common bases put the same record five times apart.'),
  ('safetystats', 'beginner', 'module', 'm01-a-rate-is-a-count-over-exposure', 7, 'Why does the engine refuse a missing base instead of assuming the most common one?', '["The base changes the count of events the engine accepts, so it has to be known before the count is checked.", "Every rate has a fixed base, and the refusal says to look it up.", "A missing base means the hours cannot be validated, since hours are only checked against a named base.", "A silent default would print one of two readings five times apart, and nobody would see a warning."]'::jsonb, 3, 'UGHELLI reads 0.776317 on the OSHA base and 3.881586 on the IOGP base, 5.000000 apart. A default would quietly hand half the callers the wrong one. Only FAR has a fixed base; every other rate needs the caller to name it, and neither the count nor the hours depend on the base.'),
  ('safetystats', 'beginner', 'module', 'm01-a-rate-is-a-count-over-exposure', 8, 'A caller passes a negative base. How does the engine''s answer differ from the one it gives when the base is missing?', '["The field is `base` both times, and the message changes to say a base must be a finite number of hours above zero.", "The message is identical, base is required with no default, because the engine treats a negative base as missing.", "The engine drops the sign and computes the rate on the positive base, flagging it in its note.", "The field named becomes `exposureHours`, since a negative base makes the whole division meaningless."]'::jsonb, 0, 'Two refusals guard the base. A missing one gets the message about naming the base with no default; a negative one gets the engine''s words: base must be a finite number of hours above zero. The field is `base` in both. The engine never repairs an input by changing its sign.'),
  ('safetystats', 'beginner', 'module', 'm01-a-rate-is-a-count-over-exposure', 9, 'A tally sheet shows half a case added to UGHELLI''s 9 recordables. The count is passed as it stands. Which field and message does the refusal carry?', '["`count`, with the message that a count must be above zero, since the engine reads a fractional count as a partial event that never finished.", "`exposureHours`, because the engine checks the hours before anything else and stops at the first input it cannot use.", "`count`, with the message that a count must be a whole number, zero or more, because an event count is not a fraction.", "None: the engine rounds the count to the nearest whole number and returns the rate on it."]'::jsonb, 2, 'The engine''s own words are: count must be a whole number, zero or more: an event count is not a fraction. The same message answers a negative count. Zero is allowed, so the tempting message about a count above zero is invented, and the engine rounds nothing.'),
  ('safetystats', 'beginner', 'module', 'm01-a-rate-is-a-count-over-exposure', 10, 'UGHELLI''s 2318640 hours are typed in as 0 by mistake. What does the engine return?', '["A rate of 0.000000, since no hours means nothing could be recorded against the count.", "A refusal naming `exposureHours`, saying a rate over no exposure is undefined.", "A refusal naming `count`, since 9 events are impossible when nobody worked.", "A rate with a null value and a note that the hours were zero."]'::jsonb, 1, 'The engine''s words are: exposureHours must be a finite number of hours above zero: a rate over no exposure is undefined. A rate divides by the hours, so with none there is nothing to divide by. 0.000000 is a real rate for zero events over real hours, which is a different situation entirely.'),
  ('safetystats', 'beginner', 'module', 'm01-a-rate-is-a-count-over-exposure', 11, 'UGHELLI had 0 fatalities in its 2318640 hours. What does the engine do with a count of zero?', '["It refuses it, because a count must be above zero for the rate to mean anything, and names the field `count` in its reply.", "It returns null for the rate, since a zero count carries no information about the underlying hours or the base.", "It returns a rate of 0.000000 and names the field `count` as a warning that zero events should be checked.", "It accepts it: zero is a real observation, and the observed FAR comes back as 0.000000."]'::jsonb, 3, 'The count rule is a whole number, zero or more, so zero passes. A period in which people worked and nothing happened is a real statement, and UGHELLI''s observed FAR of 0.000000 is exactly that. Null is kept for a period with no hours, and a warning field is only ever part of a refusal.'),
  ('safetystats', 'beginner', 'module', 'm01-a-rate-is-a-count-over-exposure', 12, 'A site counted a first aid case as recordable, so its year reads 9 recordables where 8 was right. What does the engine do with the 9?', '["It rates the 9 without complaint, because it only checks that a count is a whole number, zero or more.", "It refuses the count, because the recordable class is checked against the OSHA definition before any rate is computed.", "It rates the 9 but adds a note to its basis block saying the case class could not be confirmed by the engine.", "It asks for the case list, since a count needs its cases to be classified."]'::jsonb, 0, 'The engine does not classify events. The count arrives classified, and a wrongly classified recordable is still a whole number, so the engine rates it. Nothing in the arithmetic can repair a count that was classified wrongly, and no note or request for cases exists.'),
  ('safetystats', 'beginner', 'module', 'm01-a-rate-is-a-count-over-exposure', 13, 'Your code receives an object carrying `error` and `field` set to `exposureHours`. What can you conclude?', '["A rate was computed and the field marks the input most likely to be wrong, for a later review.", "The hours were replaced with a default and the rate in the same object uses that default.", "The call was refused over the hours and no rate was computed; the field names the input to fix.", "The call succeeded and the field is where the basis block keeps its formula."]'::jsonb, 2, 'Every function returns one of two shapes: a result object with a `basis` block, or an object with `error` and `field`. There is no third shape, so a refusal never carries a number and a rate never arrives without its basis. The field is spelled as the function spells the input.'),
  ('safetystats', 'beginner', 'module', 'm01-a-rate-is-a-count-over-exposure', 14, 'Suppose corrected timesheets show the rotation crew worked exactly the day crew''s exposure, with its single case unchanged. What would it then read on the OSHA base?', '["1.717033, the rate the rotation crew reads on the hours it actually worked, since the crew itself has not changed.", "2.500000, the day crew''s rate, since count and hours would both match.", "1.456000, the ratio the rotation pattern keeps.", "It cannot be said without the rotation crew''s headcount, which the engine would need to scale the hours."]'::jsonb, 1, '1 x 200,000 / 80000 is 2.500000. The rate follows only the count, the hours and the base, so the same count over the same hours gives the same rate whoever worked them. 1.717033 belongs to 116480 hours, and 1.456000 is the ratio of the actual hours, which would have become one.'),
  ('safetystats', 'beginner', 'module', 'm01-a-rate-is-a-count-over-exposure', 15, 'Multiply out the OSHA label''s 100 full-time workers at 40 h x 50 weeks. What do you get, and what is it in the engine?', '["200000 people, the size of the notional workforce the rate describes each year.", "200000 hours, which the engine uses as its default base when none is named in the call.", "200000 hours for each of the 100 workers, so the base is really a measure of one person''s career.", "200000 hours, which is exactly the exported `OSHA_200K`."]'::jsonb, 3, '100 times 40 times 50 is 200000, the exported `OSHA_200K`. It counts hours and has no people in it, and it is a named base the caller may pass. The engine has no default base at all, so the tempting default reading is exactly the mistake the refusal exists to stop.'),
  ('safetystats', 'beginner', 'module', 'm02-one-name-several-numbers', 1, 'The BLS example gives ABC Company 7 recordable cases and 3 DART cases in 400000 hours. What DART rate does the engine return on the 200,000 hour base?', '["3.500000, the recordable rate, since a DART case is a kind of recordable and the engine rates the whole class together.", "0.345030, the DART rate a site reads when 4 DART cases are spread over far more hours than ABC Company worked.", "1.500000, from 3 x 200,000 / 400000.", "1.5 only, because the BLS prints one decimal and the engine matches the published figure to the digit."]'::jsonb, 2, '3 x 200,000 / 400000 is 1.500000, matching the published 1.5 with a relative difference of 0. The recordable figure of 3.500000 uses the 7 recordables; the engine rates whatever count it is handed, so the DART rate needs the DART count. The engine prints six decimals whatever the source printed.'),
  ('safetystats', 'beginner', 'module', 'm02-one-name-several-numbers', 2, 'UGHELLI had 4 DART cases in 2318640 hours. What is its DART rate on the OSHA base?', '["0.345030 per 200,000 hours, from 4 x 200,000 / 2318640 with the DART count and nothing else.", "0.776317 per 200,000 hours, because a DART rate is reported on the full recordable count of 9.", "1.725149, since the DART rate is quoted per 1,000,000 hours wherever it appears.", "0.172515, since DART counts only the 2 cases where the worker was away."]'::jsonb, 0, '4 x 200,000 / 2318640 is 0.345030. 0.776317 is the recordable rate from all 9 cases, 1.725149 is the same DART count on the IOGP base, and 0.172515 is the lost time rate from the 2 lost time cases. The OSHA base was asked for, so the answer is the DART count on the 200,000 base.'),
  ('safetystats', 'beginner', 'module', 'm02-one-name-several-numbers', 3, 'A benchmarking pack asks for UGHELLI''s lost time rate per 1,000,000 hours. It had 2 lost time cases in 2318640 hours. Which figure do you send?', '["0.172515, which is the lost time rate UGHELLI already reports on the OSHA base and can be sent just as it stands.", "1.725149, the IOGP base figure for the 4 DART cases, which is how lost time is usually counted in a benchmarking pack.", "3.881586, the recordable rate on the IOGP base, since the pack''s reader will only compare total recordables.", "0.862575, from 2 x 1,000,000 / 2318640."]'::jsonb, 3, '2 x 1,000,000 / 2318640 is 0.862575, five times the OSHA figure of 0.172515. Sending 0.172515 into a column of per million figures makes the site look five times better than it is. The DART and recordable figures use larger counts and answer different questions.'),
  ('safetystats', 'beginner', 'module', 'm02-one-name-several-numbers', 4, 'UGHELLI''s counts are 9 recordables, 4 DART cases and 2 lost time cases. Why must its three rates on one base fall in that order?', '["The engine weights recordables more heavily than DART or lost time cases.", "The counts nest, 2 inside 4 inside 9, and all three share the same hours and base.", "Each class is rated over its own share of the hours.", "A coincidence; another site could show the reverse order."]'::jsonb, 1, 'Every lost time case is a DART case and every DART case is a recordable on a consistently classified site, so the counts nest and the hours and base are shared: 0.776317, 0.345030, 0.172515. The engine weights nothing and uses the same hours for every class. A lost time rate above the recordable rate on the same hours would mean the counting was wrong.'),
  ('safetystats', 'beginner', 'module', 'm02-one-name-several-numbers', 5, 'You have UGHELLI''s DART rate of 0.345030 per 200,000 hours and no calculator for the hours. How can you check its lost time rate on the same base?', '["Divide by five, because moving from DART cases to lost time cases is a change of base between the two definitions.", "Halve it: 2 lost time cases are half of 4 DART cases over the same hours, giving 0.172515.", "Subtract it from the recordable rate of 0.776317, since lost time cases are the recordables left after the DART cases.", "You cannot, because a lost time rate carries a day count."]'::jsonb, 1, 'With the hours and base fixed the rate is proportional to the count, so halving the count halves the rate: 0.345030 becomes 0.172515. A factor of five belongs to a change of base, and subtracting rates would treat nested classes as if they were separate ones.'),
  ('safetystats', 'beginner', 'module', 'm02-one-name-several-numbers', 6, 'A contractor''s OSHA TRIR of 0.776317 has been pasted into a client''s column of IOGP TRIRs. The contractor had 0 fatalities. What should the column read?', '["0.776317, because the letters TRIR already make it comparable.", "388.158576, since IOGP figures are always quoted on the 100,000,000 hour base, which is where benchmarks live.", "1.725149, which is what the contractor''s recordables convert to when they are moved onto the IOGP base.", "3.881586, the same record on the 1,000,000 hour base, with the count unchanged."]'::jsonb, 3, 'With no fatality, the one definitional difference the lesson names cannot move the count of 9, so only the base changes and the figure is multiplied by 5.000000 to 3.881586. Left at 0.776317 the contractor looks five times safer than it is. 388.158576 is the same count on the FAR base, which nobody uses for recordables.'),
  ('safetystats', 'beginner', 'module', 'm02-one-name-several-numbers', 7, 'A site had a fatality last year and reports its OSHA TRIR counted without fatalities. Why is multiplying by five not enough to set it beside an IOGP TRIR?', '["IOGP''s TRIR counts fatalities as well, so the count has to change along with the base.", "IOGP''s TRIR moves to the FAR base in a year with a fatality.", "The dead worker''s hours must first be removed from the exposure.", "The engine refuses any count that includes a fatality."]'::jsonb, 0, 'IOGP''s TRIR counts fatalities, lost workday cases, restricted workday cases and medical treatment cases per million hours. The factor of five is the whole story only when the two counts are the same. The base of an IOGP TRIR does not change with a fatality, and the engine rates whatever count it is given.'),
  ('safetystats', 'beginner', 'module', 'm02-one-name-several-numbers', 8, 'A colleague argues that UGHELLI''s 3.881586 per 1,000,000 hours is more precise than its 0.776317 per 200,000 hours, because it has more digits before the decimal point. What is right?', '["The IOGP figure is more precise, because a larger base averages the count over a larger block of hours before dividing.", "The OSHA figure is more precise, because a smaller base is closer to the hours this one site actually worked.", "Neither is more precise: both come from 9 events in 2318640 hours and carry the same information.", "The two cannot be compared, because they were produced by different functions in the engine."]'::jsonb, 2, 'Both figures are 9 x base / 2318640; only the base differs, by a factor of 5.000000. A larger base describes the same risk over a larger block of hours. How well 9 events pin down a rate is a separate question, and it has the same answer on every base. Both come from `incidenceRate`.'),
  ('safetystats', 'beginner', 'module', 'm02-one-name-several-numbers', 9, 'UGHELLI''s recordables are also run on the 100,000,000 hour base. What comes back, and how does it relate to the OSHA figure?', '["388.158576, which is 500.000000 times 0.776317, since only the base changed.", "A refusal, since that base is reserved for the fatal accident rate and the engine rejects it for any other count.", "3.881586, since the engine caps recordable rates at the IOGP base.", "0.776317 again, since a base changes only the label."]'::jsonb, 0, 'Any positive base may be passed to `incidenceRate`, so 9 x 100,000,000 / 2318640 gives 388.158576, which is 500.000000 times the OSHA figure. Only the PSE rate restricts its bases, and the base moves the number exactly as much as it moves the label.'),
  ('safetystats', 'beginner', 'module', 'm02-one-name-several-numbers', 10, 'The ratio column in the table of UGHELLI''s case classes reads 5.000000 on every row. What does that tell you?', '["The IOGP definitions add about five times as many cases to each class as the OSHA definitions do.", "UGHELLI''s DART and lost time counts happen to be in the same proportion as its recordables.", "Every class was run for five years, so each IOGP figure is a five year sum.", "Moving from the OSHA base to the IOGP base multiplies every rate by the ratio of the bases, whatever the class."]'::jsonb, 3, '1,000,000 over 200,000 is 5, so each per million figure is 5.000000 times its per 200,000 partner: 3.881586 and 0.776317, 1.725149 and 0.345030, 0.862575 and 0.172515. The case counts did not change between the columns, so the ratio says nothing about definitions or about the counts'' proportions.'),
  ('safetystats', 'beginner', 'module', 'm02-one-name-several-numbers', 11, 'A spreadsheet labels a figure LTIR, and it came from the engine''s `incidenceRate`. What has the engine verified about that label?', '["That the count was lost time cases, because the function checks the count against the case class named in the call.", "That the rate is on the IOGP base, which LTIR implies.", "Nothing: it rated the count it was given, and the name beside the number is the reporter''s claim.", "That fatalities were added, as an LTIR requires."]'::jsonb, 2, 'The engine has one function for every case class, and the name a company prints beside the number, TRIR, DART rate, LTIF or LTIR, is not something it checks. It never sees the word and cannot tell what a count of 2 is. Its basis block reports the base the caller named, which may be either one.'),
  ('safetystats', 'beginner', 'module', 'm02-one-name-several-numbers', 12, 'ABC Company worked 400000 hours, twice the 200,000 hour base. Why is its rate of 3.500000 half its count of 7 recordables?', '["The BLS halves the count for firms with more than 100 workers, so a large firm is not penalised for its size.", "The base rescales the count to 200,000 hours: 7 cases in 400000 hours happen at 3.5 per 200,000 hours.", "Half of ABC Company''s recordables were DART cases, which the engine rates separately from the rest.", "The engine divides every count by two on the OSHA base, whatever the hours worked."]'::jsonb, 1, 'The rate is count x base / hours, so 7 x 200,000 / 400000 is 3.500000: twice the base in hours means the count is halved. Nothing is discounted for firm size; ABC Company''s 3 DART cases sit inside its 7 recordables and are rated separately from the same hours. With 200,000 hours worked the rate would equal the count.'),
  ('safetystats', 'beginner', 'module', 'm02-one-name-several-numbers', 13, 'ABC Company''s recordable rate is 3.500000 and its DART rate 1.500000, both per 200,000 hours. Why must the DART figure sit below the recordable one?', '["DART rates are computed on a base five times larger, which makes the resulting figure smaller.", "The BLS discounts DART cases so that the two rates can be added without counting any case twice.", "Its 3 DART cases are among its 7 recordables, and both share the same 400000 hours and base.", "DART cases are rated on the days lost, which are fewer than the cases themselves."]'::jsonb, 2, 'Both rates are count x 200,000 / 400000, so the one with the smaller count is smaller: 3 against 7. The DART cases are the recordables serious enough to take days away, restrict duties or transfer the worker. Neither rate uses days or a different base, and nothing is discounted.'),
  ('safetystats', 'beginner', 'module', 'm02-one-name-several-numbers', 14, 'UGHELLI reads 0.776317 per 200,000 hours and ABC Company 3.500000 on the same base. What must still be checked before calling UGHELLI the safer site?', '["That both counted recordables the same way, since the rates share a base already.", "That both used the same base, since a TRIR is quoted on the OSHA base by one site and on the IOGP base by another.", "That UGHELLI''s larger number of hours has been scaled down to ABC Company''s hours before the comparison is made.", "That both are recomputed on the FAR base, since only that base makes rates from different firms comparable."]'::jsonb, 0, 'The base is already the same, so the comparison is fair as arithmetic; the rate divides out the difference in hours. Whether it is fair as safety performance depends on the two sites classifying recordables the same way, which the rates cannot show. The FAR base is for fatalities.'),
  ('safetystats', 'beginner', 'module', 'm02-one-name-several-numbers', 15, 'UGHELLI had 0 fatalities in its year. Why does that make converting its OSHA TRIR to an IOGP TRIR a clean division?', '["With no fatality the IOGP base drops to 200,000 hours.", "IOGP''s TRIR counts fatalities; with none, no fatality can change the count of 9.", "Sites with no fatalities fall outside IOGP''s definitions.", "The conversion uses the FAR, and a FAR of 0.000000 contributes nothing to either figure."]'::jsonb, 1, 'IOGP''s TRIR counts fatalities, lost workday, restricted workday and medical treatment cases, so a site whose own count left a fatality out needs a count change as well as a base change. With 0 fatalities that question never arises, and if the other classes were counted alike only the base moves: 0.776317 to 3.881586. The IOGP base is fixed at 1,000,000 hours.'),
  ('safetystats', 'beginner', 'module', 'm03-fatal-severity-and-process-safety', 1, 'IOGP''s 2024 figures are 32 fatalities in 21 fatal incidents over 4158877000 hours. What observed FAR does the engine return?', '["0.504944, from the 21 fatal incidents, since one incident is one fatal event on the record.", "0.820324, the figure IOGP published for the year the 2024 report covers.", "0.77 exactly, as published.", "0.769438 per 100,000,000 hours, from the 32 fatalities."]'::jsonb, 3, '32 x 100,000,000 / 4158877000 is 0.769438. The FAR counts people who died, so a fatality count goes in; the 21 fatal incidents give the fatal incident rate of 0.504944, a different count on the same hours. 0.820324 is the 2023 FAR, and the published 0.77 is the engine''s figure at two decimals.'),
  ('safetystats', 'beginner', 'module', 'm03-fatal-severity-and-process-safety', 2, 'A report prints 0.504944 per 100,000,000 hours for IOGP 2024 and calls it the FAR. What has gone wrong?', '["Nothing, since a fatal incident and a fatality are the same event in IOGP''s counting.", "0.504944 is the fatal incident rate from 21 incidents; the FAR uses the 32 fatalities on the same hours and reads 0.769438.", "The report used the 2023 hours, which is why the figure sits below the 0.820324 printed that year.", "The figure is on the OSHA base and needs multiplying by 500.000000 to reach the FAR."]'::jsonb, 1, 'In 2024 the 32 fatalities happened in 21 fatal incidents, because some incidents killed more than one person. The first count gives the FAR of 0.769438 and the second the fatal incident rate of 0.504944. Treating them as one event loses the people who died in the same incident. Both are per 100,000,000 hours, on the 2024 hours.'),
  ('safetystats', 'beginner', 'module', 'm03-fatal-severity-and-process-safety', 3, 'Why does `fatalAccidentRate` take no base argument when every other rate in the engine requires one?', '["The engine takes IOGP''s definition of FAR, fatalities per 100,000,000 hours, and fixes that base; every other rate is quoted on more than one.", "Fatality counts are too small for the caller to be trusted with a base, so the engine picks one for them.", "The FAR base is the product of the OSHA base and the IOGP base, so it is already implied by the two named bases in the engine''s `RATE_BASES` export.", "It does take one, but it defaults to 100,000,000 when left out, which is the only default in the engine."]'::jsonb, 0, 'The engine takes the IOGP definition of FAR and fixes its base; every other rate in this course is quoted on more than one base, so there the engine refuses to guess. A recordable rate may be per 200,000 or per 1,000,000 hours. Other bodies frame a fatal rate differently, per worker-year for one, so a FAR quoted from elsewhere needs its definition checked before it is set beside this one. There are no defaults anywhere; the FAR function simply has no base input.'),
  ('safetystats', 'beginner', 'module', 'm03-fatal-severity-and-process-safety', 4, 'The same 32 fatalities and 4158877000 hours go into `incidenceRate` with a base of 100,000,000. What comes back?', '["A refusal, since a fatality count may only be rated by the fatal accident rate function and nowhere else.", "0.769438 with a `standard` key reading IOGP safety performance indicators, FAR, exactly as the fixed base function prints it.", "0.769438, the same as the FAR function.", "0.504944, since the general function counts incidents where the FAR function counts people."]'::jsonb, 2, 'The arithmetic is identical, so the two functions agree at 0.769438; a report pack can keep that as a check against a mistyped input. The `standard` key belongs to the FAR function''s basis block only, because `incidenceRate` cannot know what its count means. The engine counts whatever it is given.'),
  ('safetystats', 'beginner', 'module', 'm03-fatal-severity-and-process-safety', 5, 'UGHELLI''s observed FAR is 0.000000 from 0 fatalities in 2318640 hours. How should it appear in a report?', '["As 0.000000 with its 2318640 hours beside it, since a zero on a few million hours says little on its own.", "As proof that the site''s true fatal accident rate sits below the IOGP figure of 0.769438 for 2024, since it had none.", "Left out of the report altogether, because the engine refuses to rate a count of zero.", "Recomputed on the OSHA base, since a FAR near zero is easier to read per 200,000 hours."]'::jsonb, 0, 'Zero is a real count, so the engine returns 0.000000, and it is correct. A site working a few million hours would rarely see a fatality even at a rate far above the industry figure, so the zero proves nothing against 0.769438. The honest report gives the zero with the hours behind it. The FAR base is fixed.'),
  ('safetystats', 'beginner', 'module', 'm03-fatal-severity-and-process-safety', 6, 'A risk assessment in another course will produce a FAR too. When should this course''s figure be written as an observed FAR?', '["Only when the base is not 100,000,000, since the base is the thing that separates an observed figure from a predicted one.", "Whenever the count is zero, since a zero FAR is the only one a predicted FAR could ever be confused with.", "Never, because a FAR is observed by definition.", "Wherever a predicted FAR could be meant, since both are per 100,000,000 hours and both are called FAR."]'::jsonb, 3, 'In this course a FAR is computed from deaths that happened over hours that were worked. The planned QRA course will teach a predicted FAR, estimated before anyone is exposed, on the same base and under the same name. Writing observed FAR wherever the two could be confused names the difference before a reader confuses it.'),
  ('safetystats', 'beginner', 'module', 'm03-fatal-severity-and-process-safety', 7, 'UGHELLI lost 96 days in 2318640 hours. What severity rate does the engine return on the 200,000 hour base?', '["48.000000, the 96 days divided by the 2 lost time cases.", "8.280716 per 200,000 hours, from 96 x 200,000 / 2318640, with no time charges added to the days.", "41.403581, the same days on the 1,000,000 hour base.", "0.172515, the lost time rate over the same hours."]'::jsonb, 1, 'The formula is daysLost x base / exposureHours, so 96 x 200,000 / 2318640 is 8.280716. 48.000000 is days per case, a different quantity with no hours in it, which the engine does not compute. 41.403581 answers the IOGP base, and 0.172515 counts cases instead of days.'),
  ('safetystats', 'beginner', 'module', 'm03-fatal-severity-and-process-safety', 8, 'UGHELLI''s 96 days lost must be restated for a reader who works per 1,000,000 hours. Which figure goes in?', '["8.280716, which is UGHELLI''s severity rate on the OSHA base and needs no conversion for a pack.", "48.000000, the days lost for each lost time case, which the pack calls its severity rate.", "41.403581, from the 96 days.", "0.862575, the lost time rate UGHELLI reads on the IOGP base of 1,000,000 hours."]'::jsonb, 2, '96 x 1,000,000 / 2318640 is 41.403581, five times the OSHA figure of 8.280716 because only the base changed. Days per case, 48.000000, has no hours in it and is a different quantity. 0.862575 counts lost time cases where the question wanted days, and answers another question.'),
  ('safetystats', 'beginner', 'module', 'm03-fatal-severity-and-process-safety', 9, 'Suppose UGHELLI''s same 96 days had been spread over 4 lost time cases in the same hours. What happens to its two measures of how serious its injuries were?', '["Both stay the same, since the 96 days lost did not change and both measures are built on the days.", "The severity rate stays at 8.280716 and the days per case fall, because only the case count changed.", "The severity rate doubles and the days per case stay at 48.000000, because more cases means more exposure.", "Both fall, since spreading the same days over more cases makes every single injury less serious on every measure."]'::jsonb, 1, 'The severity rate is days x base / hours and has no case count in it, so it stays at 8.280716. Days per case is days over cases, 96 over 2 today, so doubling the cases halves it. The days and the hours are unchanged, so nothing can move the severity rate.'),
  ('safetystats', 'beginner', 'module', 'm03-fatal-severity-and-process-safety', 10, 'Your severity rate for a site does not match a figure computed for the same record under the ANSI Z16.1 convention. Where should you look first?', '["At time charges: ANSI Z16.1 added scheduled days for fatalities and permanent disabilities, and the engine adds none.", "At the count, since ANSI Z16.1 rates the number of lost time cases while the engine''s severity rate works from the days.", "At rounding, since the two conventions are the same formula and agree once both are printed to six decimals.", "At the hours, since ANSI Z16.1 excludes overtime."]'::jsonb, 0, 'The engine''s note reads: no ANSI Z16.1 time charges are added; days are as counted by the caller. ANSI Z16.1 used the 1,000,000 hour base and charged fixed days for a fatality or a permanent disability, so the two can differ from the same record. Both conventions use days, and the note is there so the gap has a known source.'),
  ('safetystats', 'beginner', 'module', 'm03-fatal-severity-and-process-safety', 11, 'A caller passes 45.5 days lost in 1830000 hours on the 1,000,000 hour base. What does the engine do?', '["It refuses, because days lost must be a whole number, like any count.", "It rounds the days up to a whole day and returns the rate on that.", "It refuses the base, which is for the PSE rate.", "It accepts the half day and returns 24.863388, because days lost may be fractional while an event count may not."]'::jsonb, 3, 'The golden case passes 45.5 days and the engine returns 24.863388 with a relative difference of 0. A half day away can be recorded, so the engine accepts it; only a negative number of days is refused. The whole number rule belongs to event counts, and the 1,000,000 base is a named base for any rate here.'),
  ('safetystats', 'beginner', 'module', 'm03-fatal-severity-and-process-safety', 12, 'UGHELLI reported 1 Tier 1 process safety event in 2318640 hours. What is its Tier 1 PSE rate on the 200,000 hour base?', '["0.431287, since the PSE rate is quoted on the IOGP base of 1,000,000 hours.", "0.345030, which is the rate UGHELLI''s process safety events give on this base when the Tier 1 and Tier 2 events are rated together.", "0.086257, from 1 x 200,000 / 2318640, with the tier given as an input.", "0.242424, the Tier 1 golden rate, since the engine uses fixed PSE benchmarks."]'::jsonb, 2, '1 x 200,000 / 2318640 is 0.086257. The same event on the 1,000,000 base reads 0.431287. 0.345030 is the Tier 2 rate from its 4 events, and the engine rates one tier per call. 0.242424 is a separate golden case, 2 Tier 1 events in 1650000 hours, and the engine carries no benchmarks.'),
  ('safetystats', 'beginner', 'module', 'm03-fatal-severity-and-process-safety', 13, 'A caller tries to rate a Tier 1 event on the 100,000,000 hour base. What does the engine say?', '["It refuses, naming `base`: a PSE rate takes only the 200,000 or the 1,000,000 base.", "It returns a PSE rate on that base, since any positive base is accepted for any rate the engine computes.", "It refuses, naming `tier`, since the FAR base is only allowed for Tier 2 events, which are the more frequent kind.", "It returns the FAR in place of the PSE rate."]'::jsonb, 0, 'The engine''s own words: base must be 200,000 or 1,000,000 for an API RP 754 PSE rate. A PSE rate is taken consistent with the basis for calculating the Company''s occupational injury rate, so only those two bases are accepted. The tier is not what failed, and the engine never swaps one function for another.'),
  ('safetystats', 'beginner', 'module', 'm03-fatal-severity-and-process-safety', 14, 'You are handed a description of a release and asked for its PSE rate. Why can the engine not rate it as it stands?', '["The engine can classify it, but only when the released quantity is given in kilograms and the material is named in the call.", "The tier is an input, and classifying a release needs API RP 754''s licensed threshold tables, which the engine lacks.", "The engine rates releases directly and returns the tier with the rate in its basis block, so nothing is missing.", "Only Tier 3 events can be rated from a description, so the engine refuses it."]'::jsonb, 1, 'The engine does not decide whether an event is Tier 1 or Tier 2. That needs the threshold quantity tables of API RP 754, which are licensed and are not in the engine, the golden or this course. A learner given a tier can rate it; a learner given a release has to classify it elsewhere first. Tier 3 is refused.'),
  ('safetystats', 'beginner', 'module', 'm03-fatal-severity-and-process-safety', 15, 'UGHELLI''s Tier 2 PSE rate and its DART rate both read 0.345030 per 200,000 hours. What does that equality mean?', '["That each Tier 2 event caused a DART case.", "That the engine rates PSEs as injuries.", "Only that both counts are 4 over the same 2318640 hours; it says nothing about how process events relate to injuries.", "That the site is equally safe on both measures and has nothing more to learn from either one."]'::jsonb, 2, 'Both are 4 x 200,000 / 2318640, so the equality is arithmetic. A site can do well on one and badly on the other, and nothing in the rates links a process safety event to an injury. The engine has a separate `pseRate` function with its own formula and standard lines, though its arithmetic has the same shape.'),
  ('safetystats', 'beginner', 'module', 'm04-sum-then-divide', 1, 'KWALE''s three sites recorded 3, 8 and 1 recordables in 512300, 1904760 and 61480 hours. What is the field''s recordable rate per 200,000 hours?', '["0.968312, from 12 recordables over 2478540 hours, summed and then divided once.", "1.754760, the mean of the three site rates, which gives each site an equal say in the field figure.", "3.253090, the jetty''s rate, since the field is only as safe as its worst site.", "0.840001, the flow station''s rate, as the largest site."]'::jsonb, 0, 'Sum the counts to 12, sum the hours to 2478540, divide once: 12 x 200,000 / 2478540 is 0.968312. The mean of the site rates, 1.754760, weights the jetty''s 61480 hours like the flow station''s 1904760 and describes no workforce. A single site''s rate describes only that site.'),
  ('safetystats', 'beginner', 'module', 'm04-sum-then-divide', 2, 'A group report prints 1.754760 per 200,000 hours as KWALE''s recordable rate. What did the author do?', '["Pooled the counts and hours correctly, then converted the result to the IOGP base of 1,000,000 hours.", "Divided the field''s 12 recordables by the field''s hours, without the 200,000 base in the numerator.", "Averaged the three site rates.", "Added the jetty''s rate to the pooled rate of 0.968312 to allow for the highest risk site."]'::jsonb, 2, '1.171189, 0.840001 and 3.253090 average to 1.754760, the engine''s `meanOfPeriodRates`. The engine''s note reads: meanOfPeriodRates is the unweighted mean of the per-period rates over periods with hours; it is NOT the pooled rate. The pooled rate is 0.968312, and nothing in 1.754760 came from a change of base.'),
  ('safetystats', 'beginner', 'module', 'm04-sum-then-divide', 3, 'Why does the mean of KWALE''s site rates sit so far above the pooled rate?', '["The pooled rate leaves out the jetty, because a site with so few hours is set aside.", "The mean gives the jetty a weight of 0.333333 though it worked a share of only 0.024805 of the hours, and its rate is the highest at 3.253090.", "The mean is taken on the IOGP base and the pooled rate on the OSHA base.", "The pooled rate divides by more sites, which lowers it."]'::jsonb, 1, 'In the mean of rates each site carries one third, 0.333333. In the pooled rate each carries its share of the hours, and the jetty''s is 61480 over 2478540, which is 0.024805. One recordable in very few hours gives the jetty 3.253090 and the mean lets that pull the average up. The pooled rate counts every site''s hours and events once, on one base.'),
  ('safetystats', 'beginner', 'module', 'm04-sum-then-divide', 4, 'By what factor does KWALE''s mean of site rates exceed its pooled rate, and what drives the size of that factor?', '["1.812185, and it is fixed for any three sites, since a mean of three rates always sits that far above their pooled rate.", "5.000000, the ratio between the IOGP and OSHA bases, since the two figures are quoted on different bases.", "1.456000, the ratio of the two largest sites'' hours, since the flow station and compression station dominate.", "1.812185, driven by unequal hours meeting unequal rates: the jetty''s high rate sits on very few hours."]'::jsonb, 3, '1.754760 over 0.968312 is 1.812185. The gap comes from weighting: the mean weights every site equally and the pooled rate weights by hours. Unequal hours alone do not make a gap: three sites at one rate read that rate both ways, however unequal their hours. KWALE''s gap is large because its highest rate, the jetty''s 3.253090, sits on its smallest share of the hours. The IOGP five yearly FARs, with far less unequal hours, sit much closer: 0.833228 against 0.826095. Both KWALE figures are on the OSHA base.'),
  ('safetystats', 'beginner', 'module', 'm04-sum-then-divide', 5, 'Besides the rate, `pooledRate` hands back a pooled `count` and pooled `exposureHours`. What are they for KWALE, and why are they returned?', '["8 and 1904760, the largest site''s figures.", "12 and 2478540, which are needed to compute 1.754760.", "12 and 2478540, so a reader can repeat the one division that produced 0.968312 and check it.", "3 and 512300, the first site''s figures."]'::jsonb, 2, 'The engine returns the pooled count and hours beside the rate: 3 + 8 + 1 is 12 and the hours sum to 2478540, and 12 x 200,000 / 2478540 is 0.968312. The mean of rates is built from the three site rates, so the pooled totals are no part of it; it is returned beside them under its own name.'),
  ('safetystats', 'beginner', 'module', 'm04-sum-then-divide', 6, 'A mothballed fourth site with 0 hours and 0 events is added to KWALE''s list. What does the engine report?', '["Pooled rate 0.968312, a null rate for the fourth site, `periodsWithoutHours` of 1, and the mean still 1.754760.", "Pooled rate 0.968312, a rate of 0.000000 for the fourth site, and a mean of the four site rates that falls to reflect the clean site.", "A refusal naming `exposureHours[3]`, since any period with zero hours stops the call.", "A lower pooled rate, since the list now has four sites to share the 12 recordables."]'::jsonb, 0, 'A site with no hours and no events adds 0 to the count and 0 to the hours, so the pooled rate stays 0.968312. Its own rate is null, never zero, because nobody worked there. A zero would pull the mean down and make the field look safer; the engine leaves it out and counts it in `periodsWithoutHours`. Only events at a zero hour site are refused.'),
  ('safetystats', 'beginner', 'module', 'm04-sum-then-divide', 7, 'Why does the engine report the mothballed site''s rate as null where a zero might seem simpler?', '["Null tells the pooled rate to skip the site''s hours, which would otherwise be added into the sum twice over.", "A rate of zero says people worked and nothing happened; a site with no hours makes no statement at all.", "A zero would be refused by the engine''s own count check, which requires at least one event per period of work.", "Null is how the engine marks a site that belongs to another field."]'::jsonb, 1, 'Nobody worked at the mothballed site, so nothing could happen there and its rate is undefined. A zero would be read as a clean record from a site that did no work, and in the mean of rates it would drag the figure down. The site''s hours are 0, so there is nothing to double count, and a count of zero is accepted.'),
  ('safetystats', 'beginner', 'module', 'm04-sum-then-divide', 8, 'KWALE''s list is typed with a fourth site at 0 hours and 1 recordable. What comes back?', '["The pooled rate 0.968312 with the extra recordable set aside, since it sits against a site that recorded no hours.", "A pooled rate over 13 recordables and 2478540 hours, since every event must be counted somewhere in the field.", "A null rate for the fourth site and a warning in `periodsWithoutHours`, as for the mothballed site.", "A refusal naming `exposureHours[3]`."]'::jsonb, 3, 'The engine''s own words: exposureHours[3] is zero but counts has events in that period: an event needs someone at work. Setting the event aside would lose an injury, and keeping it would put it over hours that belonged to someone else. Both would produce a wrong rate, so the engine refuses the whole call and names the period.'),
  ('safetystats', 'beginner', 'module', 'm04-sum-then-divide', 9, 'The same bad entry, 0 hours with 1 recordable, is moved from fourth place to second place in the list. What changes in the engine''s reply?', '["The field becomes `exposureHours[1]`, because the index counts from zero and now points at the second entry.", "Nothing: the refusal always names `exposureHours[3]`, since the engine reports the last period it checked in the list.", "The engine now accepts the call, since only a zero at the end of a list is treated as missing data.", "The field becomes `exposureHours[2]`, since the index counts from one."]'::jsonb, 0, 'The index counts from zero, so `exposureHours[3]` was the fourth entry and `exposureHours[1]` is the second. The refusal names the position so the person fixing it can go straight to that row. A zero hour period with an event is refused wherever it sits in the list.'),
  ('safetystats', 'beginner', 'module', 'm04-sum-then-divide', 10, 'A pooled rate is refused over a site with 0 hours and 1 event. A colleague proposes typing 1 hour for that site so the call goes through. Why is that wrong?', '["It is too small a number, and a full month of hours should be typed in instead.", "The engine would still refuse, because 1 hour is below its minimum.", "It invents exposure; the fix is to find who was working when the event happened and record their hours in the right period.", "The event would then be counted twice in the field."]'::jsonb, 2, 'An event needs someone at work, so either the hours are missing or the event was recorded against the wrong site or month. Changing the zero invents hours. Any made up figure, large or small, has the same defect, and the engine has no minimum above zero. The honest repair is at the source: record the real hours or move the event.'),
  ('safetystats', 'beginner', 'module', 'm04-sum-then-divide', 11, 'A caller passes 3 counts and 2 hours figures to `pooledRate`. What does the engine return?', '["A pooled rate over the first two sites, with the unmatched third count set aside and flagged in the note.", "A refusal naming `counts`, because the counts list is the one with the extra entry.", "A pooled rate over all three counts and the two hours figures.", "A refusal naming `exposureHours`, because the two lists must be the same length."]'::jsonb, 3, 'The engine''s own words: exposureHours must be an array the same length as counts. The first count goes with the first hours and so on, and if the lists do not line up nothing can be paired. The engine names the hours list, and it never silently drops an entry.'),
  ('safetystats', 'beginner', 'module', 'm04-sum-then-divide', 12, 'Every site in a pooled call has 0 hours and 0 events. What does the engine do?', '["It returns a pooled rate of 0.000000, since no events happened anywhere and a clean record is a real result.", "It refuses the call, naming `exposureHours`: the hours sum to zero, so there is no rate.", "It returns a null rate for every site with `periodsWithoutHours` equal to the number of sites.", "It refuses, naming `counts`, since an all zero list carries no events to pool."]'::jsonb, 1, 'The engine''s own words: exposureHours sum to zero: a rate over no exposure is undefined. One empty period among many is set aside with a null rate; a series that is all empty has no rate at all. A rate of 0.000000 would claim that people worked and nothing happened.'),
  ('safetystats', 'beginner', 'module', 'm04-sum-then-divide', 13, 'IOGP''s 2020 to 2024 fatalities and hours give a five year FAR of 0.826095 by one method and 0.833228 by another. Which should a report quote?', '["0.826095, the sum then divide figure.", "0.833228, since the mean of the five yearly rates treats every year equally and so is the fairer figure.", "0.833228, since averaging the yearly rates is how IOGP itself computes its own five year rolling rate.", "Either, since the two differ only slightly and a report prints two decimals anyway."]'::jsonb, 0, 'IOGP computes its five year rate as the sum of fatalities over the sum of hours, which the engine reproduces as 0.826095. The mean of the five yearly FARs is 0.833228. Treating every year equally gives a thin year the weight of a heavy one; a pooled figure counts every hour once. Rounded to two decimals the two happen to agree, which hides the choice without making it; the engine prints six, and a report quotes the method IOGP uses.'),
  ('safetystats', 'beginner', 'module', 'm04-sum-then-divide', 14, 'KWALE''s mean of site rates is 1.812185 times its pooled rate, while IOGP''s five yearly FARs average only a little above their pooled figure. Why is the IOGP gap so much smaller?', '["IOGP rounds its yearly rates to two decimals before averaging them.", "IOGP''s figures are on a larger base, which shrinks every gap.", "The five years'' hours are far less unequal than KWALE''s site hours, so weighting by hours moves the figure much less than at KWALE.", "Five periods average out better than three."]'::jsonb, 2, 'The mean of rates and the pooled rate differ because one weights periods equally and the other weights by hours, and the gap also needs the rates to differ: KWALE''s highest rate sits on its fewest hours. KWALE''s jetty worked 61480 hours to the flow station''s 1904760; IOGP''s years run from 2544201000 to 4158877000 hours. The base scales both figures alike, and no rounding enters the engine''s 0.833228 or 0.826095.'),
  ('safetystats', 'beginner', 'module', 'm04-sum-then-divide', 15, 'KWALE''s pooled rate of 0.968312 sits much nearer the flow station''s 0.840001 than the jetty''s 3.253090. Why?', '["The engine drops the jetty from the pooled rate because a site with so few hours cannot be trusted.", "The flow station worked 1904760 of the field''s 2478540 hours, so the pooled rate weights it most.", "The pooled rate takes the median of the three site rates, and the flow station happens to sit in the middle.", "The flow station had the most recordables."]'::jsonb, 1, 'In the pooled rate each site counts in proportion to its hours, and the flow station has most of them, while the jetty''s share is 0.024805. The jetty is kept: its 1 recordable and 61480 hours are both in the sums. The engine takes no median, and its 8 recordables matter only alongside its hours.'),
  ('safetystats', 'beginner', 'module', 'm05-the-rolling-rate', 1, 'AKASO''s first twelve months hold 13 recordables in 2152250 hours, with a shutdown month and a short month inside. What is the rolling rate for that window per 200,000 hours?', '["2.026485, the mean of the monthly rates in the window, which lets each month speak for itself.", "1.209454, the rolling rate the engine prints for the first window of the series.", "1.306019, the window ending in month 15.", "1.208038, from 13 x 200,000 / 2152250, one division over the whole window."]'::jsonb, 3, 'A rolling rate is a pooled rate over the window: sum the counts, sum the hours, divide once, and 13 x 200,000 / 2152250 is 1.208038. The mean of the monthly rates, 2.026485, gives the short month the weight of a full one. 1.209454 belongs to months 2 to 13, and 1.306019 to months 4 to 15.'),
  ('safetystats', 'beginner', 'module', 'm05-the-rolling-rate', 2, 'AKASO has 15 months of data. How many rolling rates does the engine return with a window of 12, and why?', '["4, one for each complete window: 15 less 12 plus one.", "15, one for each month, with the early months built from however many months exist so far.", "12, one per month of the window.", "3, since the window moves only after a full year."]'::jsonb, 0, 'The engine returns one entry per COMPLETE window and none for the first eleven months, which have no complete window yet. Months 1 to 12, 2 to 13, 3 to 14 and 4 to 15 make 4. A partial window would be printed beside full ones under the same label while carrying less exposure, so the engine does not build one.'),
  ('safetystats', 'beginner', 'module', 'm05-the-rolling-rate', 3, 'AKASO''s first three windows read 1.208038, 1.209454 and 1.207931, and the fourth jumps to 1.306019. What moved it?', '["The shutdown month left the window, so the fourth window has more hours of real work in it than the first three.", "The short month 11 dropped out of the window, which had been holding the rolling rate down in the earlier windows.", "Month 3 left, with 0 recordables, and month 15 came in with 1.", "The fourth window is the first one the engine computes over a full year of work, so it is the one to report."]'::jsonb, 2, 'When the window moves on a month, one month drops out of the back and one comes in at the front. Window 4 runs from month 4 to month 15: month 3 had 0 recordables and month 15 has 1, so the count rises from 13 to 14 over similar hours. The shutdown month 5 and the short month 11 are inside every window.'),
  ('safetystats', 'beginner', 'module', 'm05-the-rolling-rate', 4, 'Month 11 at AKASO had 1 recordable in 18240 hours. What is its own monthly rate per 200,000 hours, and what does that figure say about month 11?', '["10.964912, which shows month 11 was the least safe month of the year by a wide margin.", "10.964912, which says little: it is one event over very few hours, and the same recordable in a full month such as month 2 reads 1.006289.", "1.006289, since one recordable in any month reads the same on this base.", "0.000000, since a short month is left out as incomplete."]'::jsonb, 1, '1 x 200,000 / 18240 is 10.964912. One event is one event; its rate is large because the hours are few, and month 2 had the same single recordable in 198750 hours and reads 1.006289. The rate depends on the hours, so the months do not read the same, and a short month is kept with its own hours.'),
  ('safetystats', 'beginner', 'module', 'm05-the-rolling-rate', 5, 'In every AKASO window the mean of the monthly rates sits well above the rolling rate, for instance 2.026485 against 1.208038 in window 1. What is the cause?', '["The short month''s rate of 10.964912 enters the mean with the weight of a full month, and it is inside every window.", "The rolling rate leaves out the shutdown month''s recordables, which the mean of the monthly rates keeps and counts in full.", "The mean of the monthly rates is computed on the IOGP base and the rolling rate on the OSHA base, a factor of five between them.", "Recordables were higher late in the year."]'::jsonb, 0, 'In the rolling rate month 11 adds 1 to the count and 18240 to the hours, so its one event counts like any other. In the mean it is one of the rates averaged, at 10.964912, and pulls the mean up. The gap is steady because the cause is steady. The shutdown month had no recordables, and both figures are on the 200,000 base.'),
  ('safetystats', 'beginner', 'module', 'm05-the-rolling-rate', 6, 'Window 1 at AKASO covers 12 months. How many monthly rates go into its mean of the monthly rates, and why?', '["Twelve, with the shutdown month entered as a rate of 0.000000.", "Twelve, with the shutdown month given the window''s own rate.", "Eleven: month 5 was a shutdown with no hours, so it has no rate and the engine leaves it out of the mean, while it still sits in the window.", "Ten, since both the shutdown and the short month drop out."]'::jsonb, 2, 'The engine''s note reads: meanOfPeriodRates is shown for comparison only; a period with no hours has no rate and is left out of that mean. Month 5 has 0 hours, so it has no rate at all; entering it as zero would pull the mean down. The short month has hours, so its rate of 10.964912 stays in, and the window reports 1 month without hours.'),
  ('safetystats', 'beginner', 'module', 'm05-the-rolling-rate', 7, 'Month 5 at AKASO was a shutdown: 0 hours and 0 recordables. What does it do to the rolling rate of each window it sits in?', '["It lowers the rolling rate, because the window is divided across twelve months though only eleven of them were worked.", "It stops the window, since the engine refuses any window that contains a month with 0 hours in it.", "It enters as a rate of 0.000000 and pulls the window down.", "Nothing: it adds 0 to the count and 0 to the hours, and is reported as 1 month without hours."]'::jsonb, 3, 'A rolling rate sums the counts and sums the hours, and a month with neither adds nothing to either sum. The engine divides by hours, never by a number of months. It refuses only a month with events and no hours; a month with neither is counted in the months without hours, 1 in every AKASO window.'),
  ('safetystats', 'beginner', 'module', 'm05-the-rolling-rate', 8, 'A caller asks for a twelve month rolling rate over only 8 months of data. What does the engine do?', '["It returns one rolling rate over the 8 months and labels it as a partial twelve month window in the basis block.", "It refuses, naming `windowPeriods`.", "It shortens the window to 8 months to fit the series and reports the change in the basis block''s `windowPeriods`.", "It returns 8 null windows, each carrying a reason that there are not yet enough months to build a full window."]'::jsonb, 1, 'The engine''s own words: windowPeriods is longer than the series: no complete window exists. A rate labelled as a twelve month rate should be one, so the engine neither shortens the window nor builds a partial one. It returns nothing it cannot compute over a complete window.'),
  ('safetystats', 'beginner', 'module', 'm05-the-rolling-rate', 9, 'A rolling call arrives with no `windowPeriods`. What does the engine reply?', '["A rolling rate with a window of 12, since that is the usual length for monthly data and so serves as the engine''s default window for a call.", "A single pooled rate over the whole series, since no window means the whole series.", "A refusal naming `windowPeriods`: it must be a whole number of periods, 1 or more, with 12 as the example for a rolling 12-month rate.", "A refusal naming `base`, since the base is checked first and the window second."]'::jsonb, 2, 'The engine''s own words: windowPeriods must be a whole number of periods, 1 or more (12 for a rolling 12-month rate). There is no default window, just as there is no default base. The 12 in the message is an example of a common value, and the engine does not quietly fall back on a pooled rate.'),
  ('safetystats', 'beginner', 'module', 'm05-the-rolling-rate', 10, 'Three periods have 0, 0 and 5000 hours with 0, 0 and 1 events, and a window of 2 is asked for. What do the two windows read?', '["Window 1 null, with the reason that it has no hours, and window 2 40.000000.", "Window 1 0.000000 and window 2 40.000000, since an empty window is a clean window.", "A refusal naming `exposureHours[1]`.", "Window 1 null and window 2 null as well, since window 2 still holds one of the empty periods."]'::jsonb, 0, 'Window 1 covers the two empty periods and has no hours, so its rate is null and the engine gives its reason: no hours in this window: the rate is undefined. Window 2 covers 0 and 5000 hours with 1 event, and 1 x 200,000 / 5000 is 40.000000; its mean of rates is also 40.000000 because only one period in it has hours. Nothing here is an event without hours.'),
  ('safetystats', 'beginner', 'module', 'm05-the-rolling-rate', 11, 'IOGP''s five years from 2020 to 2024 are run through the rolling rate with a window of 5 on the 100,000,000 base. What comes back?', '["Five windows, one per year, each carrying that year''s FAR.", "One window reading 0.826095, the same figure the pooled rate gives, because five years hold exactly one complete five year window.", "One window reading 0.833228, the mean of the yearly FARs.", "A refusal, since the window equals the series."]'::jsonb, 1, 'The IOGP five year rule is a rolling window of 5 years, and 5 years hold one complete window. A rolling rate is a pooled rate over a window, so that window reads 0.826095, the sum then divide figure. 0.833228 is the mean of the yearly rates, which the engine prints beside it for comparison. Only a window longer than the series is refused.'),
  ('safetystats', 'beginner', 'module', 'm05-the-rolling-rate', 12, 'A dashboard shows a rolling twelve month rate at month 6 of a new site''s data. What is wrong with it by the engine''s rule?', '["Nothing, as long as the six months are pooled by sum then divide and the base is named clearly in the label beside it.", "It should have been built from the mean of the six monthly rates, since there are too few months to pool them.", "It needs a window of 6 named in the call, and the engine would then label it a twelve month rate.", "It is built from six months."]'::jsonb, 3, 'The engine returns nothing until the first window is complete. A figure built from six months would sit beside figures built from twelve under the same label while carrying about half the exposure, and a reader could not tell them apart. Pooling correctly does not fix a window that is only half there.'),
  ('safetystats', 'beginner', 'module', 'm05-the-rolling-rate', 13, 'For window 4 at AKASO, months 4 to 15, the table gives 14 recordables in 2143920 hours. What rolling rate should you reach by hand?', '["1.306019, which is 14 recordables times 200,000 over the window''s 2143920 hours.", "2.111567, the mean of that window''s monthly rates, since each month in the window is a separate report.", "1.207931, window 3''s rate.", "1.208038, the first window''s rate."]'::jsonb, 0, '14 x 200,000 / 2143920 is 1.306019. 2.111567 is the window''s mean of monthly rates, printed beside the rolling rate for comparison and pulled up by the short month. 1.207931 belongs to months 3 to 14, and each window gets its own sum then divide.'),
  ('safetystats', 'beginner', 'module', 'm05-the-rolling-rate', 14, 'AKASO''s window 1 reads 1.208038 as a rolling rate and 2.026485 as a mean of monthly rates. Which is AKASO''s rolling twelve month rate, and why?', '["2.026485, because it treats every month of the year as an equal report.", "2.026485, since it includes the short month''s high rate.", "1.208038, because it gives every hour worked in the window the same weight, so a short month counts for the hours it actually holds.", "Their average, to balance the two methods."]'::jsonb, 2, 'Summing the counts and the hours gives every hour the same weight, which is what a rate over a year should mean. The mean of the monthly rates gives a short month the same say as a full one, and one event in the short month then moves a twelve month figure more than several events in full months. Averaging the two figures has no meaning.'),
  ('safetystats', 'beginner', 'module', 'm05-the-rolling-rate', 15, 'Besides the base, the label and the formula, what does the rolling rate''s basis block carry that the pooled rate''s does not?', '["`periodsWithoutHours`, so the number of empty months travels with the base.", "`windowPeriods`, so the length of the window travels with the answer.", "`standard`, since the rolling rule is an IOGP standard.", "`count`, the total events over the whole series."]'::jsonb, 1, 'The rolling rate''s basis keys are base, baseLabel, windowPeriods, formula and note; the pooled rate''s are base, baseLabel, formula and note. The months without hours are reported per window beside each rate, and a `standard` key appears only on the FAR and PSE results.'),
  ('safetystats', 'beginner', 'module', 'm06-one-report-end-to-end', 1, 'Why does this tier''s report start by reproducing the BLS worked example through the engine?', '["It sets the benchmark that every site in the report is then measured against as the target to beat each year.", "It shows the tool gets a public, fully stated answer right: 3.500000 against a published 3.5.", "The BLS figure supplies the base the engine would otherwise have to guess for the rest of the pack.", "It is the only case where the engine''s formula can be checked."]'::jsonb, 1, 'If the engine could not reproduce 3.5 from 7 cases in 400000 hours, nothing else it printed would be worth reading, so the report checks the tool against a published answer first. The engine carries no benchmark rates and never guesses a base, and the IOGP goldens are further published checks.'),
  ('safetystats', 'beginner', 'module', 'm06-one-report-end-to-end', 2, 'Which report line about ABC Company states its recordable and DART results completely enough for a reader to check with a calculator?', '["A TRIR of 3.500000 and a DART rate of 1.500000, both in line with the BLS worked example.", "A TRIR of 3.5 and a DART rate of 1.5 per 400000 hours worked in the year.", "7 recordable cases in 400000 hours, a TRIR of 3.500000 per 200,000 hours, and 3 DART cases, a DART rate of 1.500000 on the same base.", "7 recordables and 3 DART cases in the year, rated at 3.5 and 1.5."]'::jsonb, 2, 'A report line says what the number is, what it was built from and on what base, so every figure can be checked. Leaving out the base leaves 3.500000 open to be read on the IOGP base; quoting per 400000 hours confuses the hours worked with the base; and the counts without their hours cannot be divided by anyone.'),
  ('safetystats', 'beginner', 'module', 'm06-one-report-end-to-end', 3, 'The engine prints 3.500000 where the BLS prints 3.5. How should a report treat the two?', '["As the same number at different precisions: quote the engine figure, and the published one beside it labelled as published.", "As a disagreement in the sixth decimal that the report must explain before any other figure can be trusted.", "As two different rates, since the engine''s version includes a correction the BLS does not apply to its figure.", "Quote 3.5 only, since the published figure is the authority and the engine''s extra digits add nothing a reader could use at all."]'::jsonb, 0, '3.500000 and 3.5 are the same value; the golden case reports a relative difference of 0. The course quotes engine figures to six decimals so a learner can see agreement to the last digit and a copied figure is never a rounded version of what the engine printed. Nothing in the engine corrects the BLS.'),
  ('safetystats', 'beginner', 'module', 'm06-one-report-end-to-end', 4, 'IOGP published a FAR of 0.82 for 2023, from 27 fatalities in 3291382000 hours. What does the engine return?', '["0.769438, the rate the engine gives for the fatalities in the most recent year IOGP has published so far.", "0.820324 on the base the caller names, since the FAR function takes its base from the call like every other rate.", "0.826095, the five year figure that sits behind the published yearly value for 2023 in the IOGP report.", "0.820324, which rounds to 0.82."]'::jsonb, 3, '27 x 100,000,000 / 3291382000 is 0.820324, and rounded to two decimals it matches the published 0.82. 0.769438 is the 2024 FAR and 0.826095 the five year figure. The FAR function takes no base at all; its base is fixed at 100,000,000.'),
  ('safetystats', 'beginner', 'module', 'm06-one-report-end-to-end', 5, 'Your report pack computes the 2024 FAR twice, once with `fatalAccidentRate` and once with `incidenceRate` on a base of 100,000,000. Both read 0.769438. What does that check buy?', '["Confidence the FAR is right in the sense of the population it describes, since two independent methods agree on the same figure.", "Confidence the inputs were typed the same: fed the same numbers the two must agree, so a mismatch means a mistyped input.", "Nothing, since the two functions share one line of code and must return the same figure whatever is typed.", "Proof that 32 is the right count."]'::jsonb, 1, 'The fixed base function and the general function, fed the same numbers, must agree, so the check catches a mistyped count or hours. It says nothing about whether 32 fatalities was the right count or about the workforces inside the figure; the engine checks arithmetic and never classification.'),
  ('safetystats', 'beginner', 'module', 'm06-one-report-end-to-end', 6, 'The engine reproduces IOGP''s published 0.77 for 2024. What does that reproduction prove, and what does it not?', '["That the engine''s formula is the one IOGP used; the figure does not become a target, and nothing is said about any company in it.", "That 0.769438 is the rate a well run company should aim to beat, since it is the published industry figure for the year 2024.", "That every IOGP member reported its fatalities correctly, because the engine rejects any count that fails one of its classification checks.", "That the IOGP figure is exact to six decimals."]'::jsonb, 0, 'The engine carries no benchmark rates of its own; the IOGP figures are published inputs in the golden. Landing on the printed rate from the count and hours shows the formula matches. It cannot check anyone''s classification, and IOGP prints two decimals, so the engine''s six are its own arithmetic on those inputs.'),
  ('safetystats', 'beginner', 'module', 'm06-one-report-end-to-end', 7, 'Which three keys appear in the basis block of every rate function this tier uses, and what question do they answer together?', '["`base`, `standard` and `note`, which name the reporting body behind every rate.", "`count`, `exposureHours` and `formula`, so the division can be repeated.", "`base`, `baseLabel` and `formula`, which together answer the first thing a reader should ask of a rate: per what, and built how?", "`base`, `baseLabel` and `windowPeriods`, which date the rate."]'::jsonb, 2, 'Every basis block in this tier carries base, baseLabel and formula. `standard` appears only on the FAR and the PSE rate, `note` only on the severity rate and the pooled and rolling rates, and `windowPeriods` only on the rolling rate. The pooled count and hours are returned beside the rate, outside the basis block.'),
  ('safetystats', 'beginner', 'module', 'm06-one-report-end-to-end', 8, 'Two of the six functions this tier uses carry a `standard` key in their basis block. Which two, and why those?', '["The severity rate and the pooled rate, the two whose results a reader is most likely to misread without help.", "The incidence rate and the FAR, since both can be computed on the 100,000,000 hour base and need the name.", "The rolling rate and the pooled rate, since IOGP''s five year rule is a published standard for both of them.", "The FAR and the PSE rate, the two with an outside definition."]'::jsonb, 3, 'The FAR''s standard reads IOGP safety performance indicators, FAR, and the PSE rate''s reads API RP 754, API Guide to Reporting Process Safety Events section 3.3. `incidenceRate` has no standard line, because it cannot know what its count means. The severity rate and the pooled and rolling rates carry a `note` instead.'),
  ('safetystats', 'beginner', 'module', 'm06-one-report-end-to-end', 9, 'The `note` key appears on the severity rate, the pooled rate and the rolling rate results. What do those three notes have in common?', '["Each warns of the misreading a reader is most likely to make: no time charges, and the mean of rates is not the pooled figure.", "Each names the published standard the figure was taken from, so that a reader can trace the definition back to its original source.", "Each records the base the caller chose, since those are the three functions where a base is optional.", "Each flags that the result was rounded."]'::jsonb, 0, 'The severity rate''s note says no ANSI Z16.1 time charges are added; the pooled rate''s says the mean of the period rates is not the pooled rate; the rolling rate''s says the mean is for comparison only and leaves out periods with no hours. A standard lives in `standard`, the base in `base`, and none of the three bases is optional.'),
  ('safetystats', 'beginner', 'module', 'm06-one-report-end-to-end', 10, 'UGHELLI''s severity rate is recomputed on the IOGP base: 96 days in 2318640 hours now read 41.403581. Which keys of the basis block changed?', '["All four keys, since a new base means a new convention for the severity rate, with its own formula and note.", "`base` and `baseLabel`; the formula and the note on time charges stay the same.", "Only the rate itself; the basis block describes the function and never the call.", "`formula` and `note`, since the IOGP base adds ANSI Z16.1 time charges."]'::jsonb, 1, 'The block now reads base 1000000 and the label per 1,000,000 hours (IOGP); the formula is still daysLost x base / exposureHours and the note still says no time charges are added. The basis block describes the call, including the base chosen, and the engine adds time charges on no base at all.'),
  ('safetystats', 'beginner', 'module', 'm06-one-report-end-to-end', 11, 'The capstone''s rolling twelve month field names the month its window ends. What does working it take, by this tier''s rule?', '["Average the twelve monthly rates in the window, leaving out any month with no hours.", "Take the rate of the month named, as the latest month.", "Add that window''s counts and hours and divide once: a month with no hours adds nothing, and a short month counts for its own hours.", "Pool the whole series, since every window agrees."]'::jsonb, 2, 'The rolling field grades one sum then divide per window, the rule AKASO''s window 1 shows at 1.208038. Averaging the monthly rates gives the mean of rates, which for AKASO reads 2.026485. One month''s rate is a monthly rate, and windows over different months read different rates, 1.208038 to 1.306019 on AKASO.'),
  ('safetystats', 'beginner', 'module', 'm06-one-report-end-to-end', 12, 'A draft of an Associate report adds how sure anyone can be of each rate. How does the capstone brief treat that addition?', '["As answering a question nobody asked: this tier states the rate correctly and completely, and how sure it is belongs to the next tier.", "As required, since a rate on its own is incomplete at every tier and the capstone grades the rate together with its spread in every field.", "As optional extra credit, which the capstone grades whenever it is supplied beside the rate and simply ignores whenever it is left out.", "As a reason to drop the base, since how sure a rate is does not depend on the base."]'::jsonb, 0, 'The capstone asks this tier''s question, what is the rate, and every field is a count times a named base over hours. The brief says a capstone answer that brings in an interval or a limit has answered a question nobody asked. The base is never dropped; it is the first thing a rate needs.'),
  ('safetystats', 'beginner', 'module', 'm06-one-report-end-to-end', 13, 'The capstone brief lists a worked twin for each field. For the lost time rate field, which twin and base apply?', '["UGHELLI''s lost time rate, 0.172515 on the OSHA base, since a lost time rate is always quoted per 200,000 hours.", "UGHELLI''s DART rate, 1.725149 on the IOGP base, since lost time and DART are pooled in the capstone''s own count.", "KWALE''s pooled rate, 0.968312, since every capstone field is a pooled rate of the workforce in its separate parts.", "UGHELLI''s lost time rate, 0.862575 on the IOGP base."]'::jsonb, 3, 'The brief pairs the lost time field with UGHELLI lost time, 0.862575, on the 1,000,000 base, and warns that the same count on the OSHA base is five times smaller. The DART count is a different class, and KWALE''s pooled rate is the twin of the field for a workforce in parts.'),
  ('safetystats', 'beginner', 'module', 'm06-one-report-end-to-end', 14, 'The capstone brief says most wrong answers at this tier come from two mistakes that are visible on paper before any division. Which two?', '["Rounding too early and quoting two decimals.", "The wrong base, and pooling the wrong way, which is why the brief says to write down the count, the hours and the base for each field first.", "Forgetting the interval and omitting a limit.", "Using headcount and forgetting the tier."]'::jsonb, 1, 'The brief tells the learner to write down, for each field, the count, the hours and the base before computing anything, because a wrong base or a mean of rates is visible at that stage. Intervals are out of scope at this tier, and the engine has no headcount input to misuse.'),
  ('safetystats', 'beginner', 'module', 'm06-one-report-end-to-end', 15, 'When reading any result from the engine, what order does this tier teach, and why?', '["Read the number first, then check it against the published value, since the published value settles the base.", "Read the note first and skip the rest of the block, since only the note can change the meaning of the rate.", "Read the basis block before the number: check the base, then the formula, then any note.", "Read the number and its label only."]'::jsonb, 2, 'Checking the base against the base you meant, the formula against the quantity you meant, and the note for the likely misreading takes a few seconds and prevents the factor of five between OSHA TRIR and IOGP TRIR. Many results have no published value to compare against, and a note is only one of several keys.'),
  ('safetystats', 'beginner', 'final', null, 1, 'UGHELLI''s 4 DART cases in 2318640 hours are wanted for an IOGP comparison, per 1,000,000 hours. What figure is right?', '["0.345030, the DART rate on the 200,000 hour base, which can go straight into a per million comparison.", "1.725149, which is 4 x 1,000,000 / 2318640 and five times the OSHA base DART rate.", "3.881586, since IOGP compares recordables and the DART count should be widened to all 9 cases first.", "0.862575, the DART count on the million base."]'::jsonb, 1, '4 x 1,000,000 / 2318640 is 1.725149, which is 5.000000 times 0.345030. Putting 0.345030 into a per million column understates the site five times over. 3.881586 uses the 9 recordables and 0.862575 the 2 lost time cases, so each rates a different class from the one asked for.'),
  ('safetystats', 'beginner', 'final', null, 2, 'UGHELLI''s 4 Tier 2 process safety events are rated per 1,000,000 hours of its 2318640. What does the engine return?', '["0.431287, since a Tier 2 event is rated like a Tier 1 event and the tier label changes only the formula line.", "0.345030, the same count per 200,000 hours.", "5.454545, since Tier 2 rates are taken from the golden and apply to every site.", "1.725149, from 4 x 1,000,000 / 2318640, on one of the two bases a PSE rate accepts."]'::jsonb, 3, 'Four events times a million over 2318640 hours gives 1.725149, and the million hour base is one of the two a PSE rate may use. What sets the answer is the count the tier carries: UGHELLI''s one Tier 1 event gives 0.431287 on this base. The golden''s 5.454545 comes from a different workplace, and a figure on the smaller base cannot be moved across bases unchanged.'),
  ('safetystats', 'beginner', 'final', null, 3, 'The vendored golden checks nine Tier 2 events against 1650000 hours per million. What does the engine return, and does it agree?', '["5.454545, with a relative difference of 0.", "0.242424, which is the rate the golden records for this case on the million hour base.", "A refusal naming `tier`, since the engine rates only Tier 1 events against the golden and holds every Tier 2 case back.", "1.725149 per 1,000,000 hours, since every Tier 2 rate on the million base reads the same whatever the hours."]'::jsonb, 0, '9 x 1,000,000 / 1650000 is 5.454545, and the golden rate is the same. 0.242424 is the other golden case, 2 Tier 1 events in the same hours on the 200,000 base. Tiers 1 and 2 are both accepted, and the engine divides once on the base named.'),
  ('safetystats', 'beginner', 'final', null, 4, 'Two Tier 1 events are logged over 1650000 hours in a second golden case, and the caller names the 200,000 base. What does the engine print?', '["0.086257, which is the Tier 1 rate for any site with a single Tier 1 event recorded in a year.", "5.454545, since Tier 1 weighs more.", "0.242424 per 200,000 hours, from 2 x 200,000 / 1650000, matching the golden.", "A refusal naming `base`."]'::jsonb, 2, '2 x 200,000 / 1650000 is 0.242424. 0.086257 is UGHELLI''s single event over its own 2318640 hours, a different workplace. The engine weights no tier; the tier is an input that names which count is being rated. Both the 200,000 and 1,000,000 bases are accepted for a PSE rate.'),
  ('safetystats', 'beginner', 'final', null, 5, 'The golden case for the severity rate puts 312 days lost over 400000 hours on the 200,000 base. What does the engine return?', '["8.280716, the severity rate the engine prints on the OSHA base for every site in the golden set of cases.", "24.863388, since 312 days must be converted to the IOGP base before a severity rate is computed.", "156.000000, which is 312 x 200,000 / 400000: days lost times the base over the hours.", "3.500000, since the 400000 hours are the BLS example''s and give the same rate."]'::jsonb, 2, '312 x 200,000 / 400000 is 156.000000, which the golden records with a relative difference of 0. 8.280716 is UGHELLI''s own severity rate from 96 days, and 24.863388 the second golden case of 45.5 days on the million base. 3.500000 is a recordable rate from a count of 7 over the same hours.'),
  ('safetystats', 'beginner', 'final', null, 6, 'Looked at alone, the compression station at KWALE logged 3 recordables across 512300 hours. What does that one site read?', '["0.968312, since every site in a field reads the field''s pooled rate once the counts are summed.", "1.171189: its 3 cases over its own 512300 hours, on the 200,000 base.", "1.754760, the mean of the three site rates, which is what each site''s own rate is measured against.", "0.840001, the rate KWALE''s flow station reads over its own hours."]'::jsonb, 1, 'Each site rate is its own count over its own hours: 3 x 200,000 / 512300 is 1.171189. 0.968312 is the whole field''s pooled rate, 1.754760 the unweighted mean of the three site rates, and 0.840001 the flow station''s rate from 8 recordables in 1904760 hours.'),
  ('safetystats', 'beginner', 'final', null, 7, 'KWALE''s jetty reads 3.253090 per 200,000 hours, the highest site rate on the field. What is behind that figure?', '["A single recordable in only 61480 hours.", "The jetty had the most recordables of the three sites, and its rate follows its count.", "The jetty''s rate is computed on the IOGP base while the other two are on the OSHA base, so it looks larger than theirs.", "The jetty''s hours are counted twice, once for the site and once again for the pooled total of the field."]'::jsonb, 0, '1 x 200,000 / 61480 is 3.253090. One event over very few hours makes a large rate, which is why the jetty can pull an unweighted mean of rates up so far. The flow station had the most recordables, 8, and all three site rates are on the same base.'),
  ('safetystats', 'beginner', 'final', null, 8, 'The jetty worked 61480 of KWALE''s 2478540 hours. What fraction is that, and in which of the two field figures does it act as the jetty''s weight?', '["0.333333, one site of three, and it is the jetty''s weight in the pooled rate.", "0.024805, and it is the jetty''s weight in the unweighted average of the site rates.", "3.253090, its own rate, which sets its weight.", "0.024805, and it is the jetty''s weight in the pooled rate of 0.968312."]'::jsonb, 3, 'Dividing 61480 by 2478540 gives 0.024805. Sum then divide lets each site count in proportion to the hours it worked, so that fraction is the jetty''s say in 0.968312. An unweighted average of the three site rates hands every site 0.333333 whatever it worked, which is why the jetty''s 3.253090 lifts that average so far.'),
  ('safetystats', 'beginner', 'final', null, 9, 'Month 4 of the AKASO stream holds 3 recordables over 205880 hours. Taken on its own, what does that month read?', '["2.914319, from 3 x 200,000 / 205880, the month''s own count over its own hours.", "1.883239, the first month''s rate, since every month in a rolling series reads the rate of the series'' opening month.", "1.208038, the rate of the window holding month 4.", "10.964912, as the worst month of the year."]'::jsonb, 0, '3 x 200,000 / 205880 is 2.914319. A month has its own rate, and the rolling rate of 1.208038 is the pooled figure over twelve months. 10.964912 belongs to month 11, whose single recordable fell in only 18240 hours; the largest monthly rate comes from the fewest hours here.'),
  ('safetystats', 'beginner', 'final', null, 10, 'AKASO''s window 2 covers months 2 to 13: 13 recordables in 2149730 hours. What rolling rate does the engine print?', '["2.028541, the mean of the monthly rates in the window, since the engine reports that figure as the window''s rate.", "1.209454: sum the window''s 13 cases and its 2149730 hours, then divide once on the base.", "1.208038, since the rolling rate stays fixed until the count in the window changes.", "1.207931, the rate of the window running from month 3 to month 14."]'::jsonb, 1, '13 x 200,000 / 2149730 is 1.209454. The count matches window 1 but the hours differ, so the rate moves slightly; a rate follows hours as well as counts. 2.028541 is window 2''s mean of monthly rates, printed beside it for comparison only, and 1.207931 is window 3.'),
  ('safetystats', 'beginner', 'final', null, 11, 'AKASO''s window 3 prints 1.207931 and, beside it, 2.027310. Which one is the rolling rate, and what is the other?', '["2.027310 is the rolling rate, and 1.207931 is the same window with the short month taken out of it.", "1.207931 is the rolling rate on the OSHA base, and 2.027310 is the same rate restated on a larger base.", "1.207931 is the rolling rate; 2.027310 is the mean of the monthly rates.", "Both are rolling rates, one per half of the window."]'::jsonb, 2, 'The rolling rate is the window''s summed recordables over its summed hours, 1.207931. The engine prints the mean of the monthly rates, 2.027310, for comparison only; it sits higher because the short month''s rate enters with the weight of a full one. Both are on the 200,000 base and neither drops a month.'),
  ('safetystats', 'beginner', 'final', null, 12, 'IOGP''s 2022 FAR was 1.279566, from 33 fatalities in 2579000000 hours, the highest of the five years. What does this tier say about reading one high year?', '["It shows the industry became less safe in 2022, since the rate rose above every other year in the window.", "It should be removed from the five year figure as an outlier before the window is pooled.", "It is a data error, since the engine refuses a FAR above one.", "Much of the movement between years is what a small count does; a five year window pools more events and moves less."]'::jsonb, 3, 'The yearly rates run from 0.550271 in 2020 to 1.279566 in 2022, and a single year rests on a few dozen fatalities, so much of that swing is small count noise. A five year window pools more events and hours. Nothing in this tier removes a year from a window, and the engine refuses no FAR for its size.'),
  ('safetystats', 'beginner', 'final', null, 13, 'IOGP''s five year FAR by sum then divide, 0.826095, sits a little below the mean of its yearly FARs, 0.833228. What pulls it down?', '["The pooled figure leaves out 2022, whose rate of 1.279566 was the highest of the five years.", "The mean of rates is computed on a larger base, which lifts it by a small fixed factor.", "Both are rounded to two decimals first, and the rounding lowers the pooled figure.", "Hour weighting: 2022''s high rate of 1.279566 sits on fewer hours than an average year, and 2024''s lower 0.769438 on the most."]'::jsonb, 3, 'The mean gives each year a fifth; the pooled figure weights each year by its hours, which run from 2544201000 in 2020 to 4158877000 in 2024. 2022, the highest rate, worked fewer hours than an average year and so counts for less than a fifth, while 2024, below the mean, worked the most and counts for more. Together they pull the pooled figure a little under the mean of rates. Every year is in both figures, both are on the 100,000,000 base, and the engine rounds nothing.'),
  ('safetystats', 'beginner', 'final', null, 14, 'A caller passes a negative number of days to `severityRate`. What does the engine say?', '["A refusal naming `daysLost`: days lost must be a finite number of days, zero or more.", "A refusal naming `count`, with the message that an event count cannot be a fraction or below zero.", "A severity rate of 0.000000, since negative days are read as no days lost at all.", "A refusal naming `base`, since days lost are checked only after a base is named in the call."]'::jsonb, 0, 'The engine''s own words are: daysLost must be a finite number of days, zero or more. The severity rate takes days, which may be fractional but may not be negative, and the field it names is `daysLost`. The count message belongs to `incidenceRate`, and the engine never turns a bad input into zero.'),
  ('safetystats', 'beginner', 'final', null, 15, 'A caller asks for a PSE rate and leaves the tier out. What comes back?', '["A rate on the assumption the events are Tier 1, since the more serious tier is the safer default for a report.", "No rate; the engine refuses and names the `tier` field.", "A rate with the tier set to null in the formula line, which reads PSE count x base / total work hours.", "A refusal naming `pseCount`, since a count without a tier cannot be matched to any class of event."]'::jsonb, 1, 'The engine''s own words are: tier must be 1 or 2: classify the events against API RP 754 before rating them. The same message answers tier 3. The engine never picks a tier for the caller, because classifying an event needs the licensed threshold tables it does not hold.'),
  ('safetystats', 'beginner', 'final', null, 16, '`fatalAccidentRate` is called with 32 fatalities and 0 hours. Its base is fixed. Does the fixed base change what happens?', '["Yes: the fixed base lets the engine fall back on IOGP''s 2024 hours of 4158877000.", "Yes: a FAR with no hours returns 0.000000.", "No: with no hours there is no FAR, fixed base or not, and `exposureHours` is the field refused.", "No, but the field named is `fatalities`."]'::jsonb, 2, 'The engine''s own words: exposureHours must be a finite number of hours above zero: a rate over no exposure is undefined. A fixed base does not mean the FAR accepts anything; with no hours there is no rate. The engine carries no benchmark hours and never invents a zero.'),
  ('safetystats', 'beginner', 'final', null, 17, 'A count of minus 1 recordable reaches `incidenceRate`. Which message comes back?', '["A message that negative counts are corrected to zero, followed by a rate of 0.000000 on the base named.", "The same one a fractional count gets: a count must be a whole number, zero or more.", "A refusal naming `exposureHours`, as a mistyped box.", "A rate on the absolute value, 1 recordable."]'::jsonb, 1, 'The engine''s own words for both a fractional and a negative count: count must be a whole number, zero or more: an event count is not a fraction. The field named is `count`. The engine corrects nothing and never guesses which box was mistyped.'),
  ('safetystats', 'beginner', 'final', null, 18, '`severityRate` is called with UGHELLI''s 96 days and 2318640 hours and no base. What happens?', '["It is refused with the same base message `incidenceRate` gives: there is no default.", "It returns 41.403581, since the severity rate defaults to the ANSI Z16.1 base of 1,000,000 hours.", "It returns 8.280716 on the OSHA base, the base the severity rate always uses.", "It returns 48.000000 days a case, since without a base the engine divides by the cases."]'::jsonb, 0, 'The severity rate has two common bases, the OSHA style 200,000 and the ANSI Z16.1 convention''s 1,000,000, so the engine will not guess. A missing base draws exactly this message from `incidenceRate` too. Days per case is not a figure the engine computes on any call.'),
  ('safetystats', 'beginner', 'final', null, 19, 'A reader wants UGHELLI''s days lost per lost time case from the engine. Which function returns it?', '["`severityRate`, which returns 48.000000 when the base is set to the number of lost time cases.", "`incidenceRate`, called with the days as the count and the lost time cases passed in as the hours.", "None: it is derived by hand, 96 over 2.", "`pooledRate`, whose meanOfPeriodRates returns the average days for each lost time case in the list."]'::jsonb, 2, 'The engine does not compute days per case. Its one function in this area, `severityRate`, returns days lost times a base over hours, 8.280716 per 200,000 hours for UGHELLI. Days per case, 96 over 2, is 48.000000 and has no hours in it. Passing cases where hours belong would produce a number with no meaning.'),
  ('safetystats', 'beginner', 'final', null, 20, 'A report says injuries became less serious this year because days lost per case fell. What could still be true of the site''s severity rate?', '["It must have fallen too, since both measures are built from the same days lost and move together.", "It must be unchanged, since the severity rate counts cases and the days per case counts days.", "Nothing, since the engine refuses a severity rate once days per case is known.", "It could have risen, because more injuries each slightly shorter can raise total days per block of hours."]'::jsonb, 3, 'Days per case divides by the number of cases; the severity rate divides by hours. A site with more injuries, each a little shorter, can show falling days per case and a rising severity rate at once. Both readings are arithmetic on real records, which is why any figure for how serious injuries were must travel with its denominator.'),
  ('safetystats', 'beginner', 'final', null, 21, 'In one incident, 3 workers die. How many does the incident add to the count behind the FAR, and to the count behind the fatal incident rate?', '["3 to the FAR count and 1 to the fatal incident count.", "1 to each count, since both rates count events, and one incident is one event on the record however many died.", "3 to each count, as both rates count deaths.", "3 to the FAR count and none to the other."]'::jsonb, 0, 'The FAR counts people who died; the fatal incident rate counts incidents that killed someone. IOGP''s 2024 figures show the difference: 32 fatalities in 21 fatal incidents give 0.769438 and 0.504944 on the same hours and the same base. Counting the incident once in the FAR loses two of the deaths.'),
  ('safetystats', 'beginner', 'final', null, 22, 'Why does the FAR use a base as large as 100,000,000 hours?', '["IOGP''s members work about that many hours a year, so the base describes one year of the whole industry.", "It is the product of the OSHA and IOGP bases, which keeps the FAR consistent with both conventions.", "Fatalities are rare, and a base that size turns the rate into a number near one that a reader can compare.", "A small base would round the FAR to zero in the engine."]'::jsonb, 2, 'The 2024 figure rests on 32 fatalities over more than four billion hours; on the 200,000 base that rate would be well under one hundredth, awkward to read and easy to misprint. A base of 100,000,000 gives 0.769438. IOGP''s yearly hours run to billions and have nothing to do with the choice of base, and the engine prints six decimals on any base.'),
  ('safetystats', 'beginner', 'final', null, 23, 'A PSE rate report must sit beside a company''s recordable rate, which is published per 200,000 hours. Which base should the PSE rate use?', '["100,000,000, since process safety events are rare and rated like fatalities on the largest base the engine has.", "200,000, to match the injury rate.", "1,000,000, since API RP 754 fixes the million hour base for every PSE rate whatever the injury rate uses.", "Any base at all, since the engine accepts any positive number of hours as a base for a PSE rate."]'::jsonb, 1, 'The engine takes the PSE rate consistent with the basis for calculating the Company''s occupational injury rate, so a company reporting per 200,000 hours reports its PSE rate the same way. Only 200,000 and 1,000,000 are accepted, and the FAR base is refused.'),
  ('safetystats', 'beginner', 'final', null, 24, 'Which exported `RATE_BASES` name should a caller pass to rate UGHELLI''s recordables for an IOGP pack, and what label comes back?', '["`OSHA_200K`, since IOGP converts every OSHA figure itself, labelled per 200,000 hours.", "`FAR_100M`, labelled per 100,000,000 hours (FAR, IOGP), since IOGP''s name is on that label.", "None: the engine picks it.", "`IOGP_1M`, 1000000, labelled per 1,000,000 hours (IOGP)."]'::jsonb, 3, 'The exported names are `OSHA_200K` 200000, `IOGP_1M` 1000000 and `FAR_100M` 100000000. On `IOGP_1M` UGHELLI reads 3.881586 with the label per 1,000,000 hours (IOGP). IOGP''s name appearing on the FAR label does not make it the base for recordables, and the engine picks no base itself.'),
  ('safetystats', 'beginner', 'final', null, 25, 'A contractor''s OSHA DART rate of 0.345030 is pasted into a column of IOGP per million DART rates. What happens to the contractor''s standing, and what should the entry read?', '["It looks five times worse than it is, since per million figures run smaller; the entry should stay as it is.", "It looks five times better than it is; the entry should read 1.725149.", "Nothing changes, as a DART rate needs no conversion.", "It looks slightly better; it should read 0.862575."]'::jsonb, 1, 'The same 4 DART cases in 2318640 hours read 0.345030 per 200,000 and 1.725149 per 1,000,000. Beside per million figures, the smaller number looks five times better than the record. Dividing by five goes the wrong direction, and 0.862575 is the lost time rate on the IOGP base.'),
  ('safetystats', 'beginner', 'final', null, 26, 'A site''s lost time rate reads above its DART rate on the same hours and base. What does that tell you?', '["The site had a bad year for lost time and a good year for restricted work.", "The two rates were computed on different bases and cannot be compared.", "Nothing, since the engine never checks the order of classes.", "The counting is inconsistent somewhere: on one set of definitions lost time cases are a subset of DART cases, so they cannot outnumber them."]'::jsonb, 3, 'On a site that classifies consistently every lost time case is also a DART case, so with shared hours and base the lost time rate cannot exceed the DART rate; UGHELLI''s 2 inside 4 give 0.172515 and 0.345030. Mixing definitions is one way to break the order: IOGP''s lost time count takes in fatalities, so beside a DART count drawn up another way it can run higher. The premise already fixes the base. It is true that the engine checks no order, which is exactly why the reader must.'),
  ('safetystats', 'beginner', 'final', null, 27, 'With KWALE''s mothballed fourth site listed, the engine''s mean of rates still reads 1.754760. Over how many sites is that mean taken?', '["Three, the sites with hours.", "Four, with the mothballed site''s rate entered as 0.000000, which is why the figure matches the three site mean exactly.", "Four, with the mothballed site given the pooled rate of 0.968312 so that it cannot pull the mean in either direction.", "Two, since the jetty is also set aside for having too few hours to give a trustworthy rate."]'::jsonb, 0, 'The mean is taken over periods with hours; the mothballed site''s rate is null and it is counted in `periodsWithoutHours`. Entered as zero it would pull the mean below 1.754760. The engine never fills a null with another site''s figure, and the jetty is kept with its 61480 hours.'),
  ('safetystats', 'beginner', 'final', null, 28, 'In a rolling call, the first window covers two periods with no hours. Does the engine list that window, and what does it say?', '["No, empty windows are dropped, so the list simply starts at the first window that has any hours in it.", "Yes, with a rate of 0.000000, since no events happened in it and an empty window is a clean one.", "Yes, with a null rate and the reason: no hours in this window: the rate is undefined.", "No, the whole call is refused, naming `exposureHours` for the empty periods."]'::jsonb, 2, 'The window is still listed, with a reason, so a reader sees that a window existed and had nothing in it. A zero would claim that people worked and nothing happened. A whole call is refused only when a period has events and no hours, or when the hours sum to zero.'),
  ('safetystats', 'beginner', 'final', null, 29, 'The engine has one function for TRIR, DART rate and lost time rate. Why only one?', '["The arithmetic is the same for every class; only the count changes, and the caller classifies it.", "It detects the class from the size of the count and applies the matching definition by itself.", "Only recordables are rated; DART and lost time rates are derived from the TRIR by a fixed fraction.", "Two separate functions would disagree about the base, which is why they were merged into one."]'::jsonb, 0, 'Every class is count x base / exposureHours, so `incidenceRate` serves all three with the caller''s count. The engine never sees the word DART and cannot tell what a count of 4 is. UGHELLI''s DART rate comes from its 4 DART cases, and no fixed fraction of its TRIR is involved.'),
  ('safetystats', 'beginner', 'final', null, 30, 'In AKASO''s window 1, how does the short month 11 enter the rolling rate?', '["As its own rate of 10.964912, entered once with the weight of a full month of work beside the others.", "As 1 recordable added to the count and 18240 hours added to the hours, so its one event counts like any other in the window.", "It is left out, since a month with so few hours is treated like the shutdown month.", "As 1 recordable, with its hours rounded up to a full month."]'::jsonb, 1, 'In the rolling rate the short month counts for exactly the hours it holds: 13 recordables over 2152250 hours give 1.208038. Its own rate of 10.964912 enters only the mean of the monthly rates, where it pulls that figure up to 2.026485. Only the shutdown month, with no hours, has no rate.'),
  ('safetystats', 'beginner', 'final', null, 31, 'When a twelve month window moves on by one month, what can change the rolling rate?', '["Every month in the window, since the engine recomputes each month''s weight whenever the window moves on by one.", "Only the newest month, since the oldest month stays in the window until the end of the year it belongs to.", "Nothing, since a rolling rate is fixed once a full year has been counted.", "Only the month leaving and the month joining."]'::jsonb, 3, 'One month drops out of the back and one comes in at the front, and the rate changes only by what those two months differ by. That is why AKASO''s first three windows read 1.208038, 1.209454 and 1.207931, and why window 4 rises to 1.306019 when a month with 1 recordable replaces one with none.'),
  ('safetystats', 'beginner', 'final', null, 32, 'UGHELLI''s severity rate is 8.280716 per 200,000 hours. What can that single figure tell you about how its days were lost?', '["That its injuries were mostly long absences, since a severity rate above the lost time rate means long cases.", "That each injury kept a worker away for about 8 days, since the rate is days for each case on the base.", "Not whether they came from a few long absences or many short ones; the rate rises with either.", "That time charges were added for its most serious case."]'::jsonb, 2, 'A severity rate says how many days were lost for each block of hours worked; it rises when injuries are more serious or more frequent and cannot say which. It is not a per case figure, which for UGHELLI would be 48.000000 days. The engine adds no time charges.'),
  ('safetystats', 'beginner', 'final', null, 33, 'The pooled rate''s note reads: meanOfPeriodRates is the unweighted mean of the per-period rates over periods with hours; it is NOT the pooled rate. What is the note guarding against?', '["A reader using the pooled rate for a single site, which the note says must be taken from the mean instead.", "A reader assuming the pooled rate leaves out the periods with no hours, which the note says it counts as zeros.", "A reader taking the mean of site rates, printed beside the pooled rate, for the rate of the whole workforce.", "A reader rounding the pooled rate."]'::jsonb, 2, 'The engine returns both figures, labelled, so both can be seen; the note says which one is the pooled rate. On KWALE the mean is 1.754760 and the pooled rate 0.968312. Periods with no hours add nothing to the pooled sums and are left out of the mean, never counted as zeros.'),
  ('safetystats', 'beginner', 'final', null, 34, 'Feed the fatalities and hours for 2020 to 2024 into the pooling function, naming the FAR base. Which two figures does the result carry?', '["0.826095, with 0.833228 as the mean of the five yearly rates beside it.", "0.833228 as the rate, with 0.826095 beside it as the figure IOGP publishes for its members.", "0.769438, the latest year''s rate, with the other years reported only in the list of period rates.", "0.826095, with 1.279566 beside it as the highest year."]'::jsonb, 0, 'The pooled rate sums 14, 20, 33, 27 and 32 fatalities over the five years'' hours and divides once: 0.826095. The companion is the unweighted mean of the yearly FARs, 0.833228, labelled so it is not taken for the pooled rate. The same 0.826095 is what a rolling window of 5 returns over these years.'),
  ('safetystats', 'beginner', 'final', null, 35, 'The capstone''s Tier 1 PSE field names a Tier 1 count. What does working it involve, per the capstone brief?', '["Classify each listed release against API RP 754 first, and then rate whichever events come out as Tier 1.", "Rate Tier 1 and Tier 2 together, since the capstone asks for all process safety events in one rate.", "Use the FAR base, since process safety events are rare in the way fatalities are and share that base.", "Rate the stated count on the brief''s base."]'::jsonb, 3, 'The brief says the Tier 1 PSE rate takes the Tier 1 count it states; you are not asked to classify anything, because the engine never does. Its worked twin is UGHELLI''s Tier 1 rate, 0.086257 per 200,000 hours. The engine rates one tier per call and refuses the FAR base for a PSE rate.'),
  ('safetystats', 'beginner', 'final', null, 36, 'The capstone field for a workforce in parts is a recordable rate. Which twin and which rule does the brief attach to it?', '["KWALE''s mean of site rates, 1.754760, and an equal weight for every part of the workforce.", "KWALE''s pooled 0.968312 and sum then divide.", "AKASO''s first window, 1.208038, and a rolling window over the parts of the workforce listed in the brief.", "UGHELLI''s 0.776317 and the named base, since a workforce in parts is rated one part at a time."]'::jsonb, 1, 'The brief pairs this field with KWALE pooled, 0.968312, and the rule sum then divide: add every part''s recordables, add every part''s hours, divide once. The mean of the parts'' rates is a different number and is not what is asked for. AKASO is the rolling field''s twin and UGHELLI''s rate is a single site''s.'),
  ('safetystats', 'beginner', 'final', null, 37, 'A contractor reports per head: 3 recordables among 40 people. Your group rates on hours. What must you ask for before the figure can go into your table?', '["Nothing, since 3 among 40 converts to a rate on the OSHA base by the 100 full-time worker reading of the label.", "The hours those 40 people actually worked in the period.", "The headcount of your own group, so the two per head figures can be set on a common base in the engine.", "The contractor''s own base."]'::jsonb, 1, 'The engine has no headcount input; a headcount says nothing about how long anyone worked. The two crews of 40 read the same 2.500000 per 100 people and 2.500000 and 1.717033 per 200,000 hours because their hours differed. Only the contractor''s hours can turn 3 recordables into a rate.'),
  ('safetystats', 'beginner', 'final', null, 38, 'The OSHA base label reads 100 full-time workers, 40 h x 50 weeks. What does that make a rate of 3.500000 per 200,000 hours mean?', '["At the observed rate, an imaginary 100 full-time workers over a working year would have about three and a half recordables.", "3.5 recordables for each 100 people on the firm''s own payroll in the year.", "3.5 recordables for every 40 hours worked in the firm.", "3.5 recordables over the 50 weeks of the firm''s year."]'::jsonb, 0, '100 times 40 times 50 is 200000, so the base is a reading scale: the rate expresses the firm''s own experience as a count for an imaginary full-time workforce over a year. Nobody counted the firm''s people to produce it, so it says nothing per head, and it is a rate per 200,000 hours with no week or 40 hour block in it.'),
  ('safetystats', 'beginner', 'final', null, 39, 'The engine returns `baseLabel` with every rate. Why does it matter that the label travels with the number?', '["The label records the case class, so a reader can tell a DART rate from a recordable rate by the label alone.", "The label holds the count and the hours the rate came from, so the division can be repeated by any reader.", "The base falls off first when a figure is copied, and nothing in the number itself warns a reader.", "The label marks whether the rate was checked against a published figure in the golden."]'::jsonb, 2, 'OSHA TRIR and IOGP TRIR share three letters and differ by a factor of five, and nothing in the number warns a reader which it is. The label, such as per 1,000,000 hours (IOGP), says which base produced the figure. It carries no case class, no counts and no golden check.'),
  ('safetystats', 'beginner', 'final', null, 40, 'Your group averages its five sites'' recordable rates for its annual report. What is the one change that makes the figure the group''s rate?', '["Weight each site''s rate by its headcount before averaging, so large sites count for more.", "Drop the smallest site, whose rate would otherwise pull the average up.", "Average the rates on the IOGP base in place of the OSHA base.", "Add the sites'' recordables and their hours, and divide once on the base."]'::jsonb, 3, 'The group''s rate is the events over the hours of the whole workforce: sum then divide, as KWALE''s 12 recordables over 2478540 hours give 0.968312 against a mean of site rates of 1.754760. Headcount carries no exposure, dropping a site loses its events and hours, and a change of base scales both figures alike.'),
  ('safetystats', 'beginner', 'final', null, 41, 'UGHELLI''s recordable rate is 0.776317 per 200,000 hours. What does it read on the 100,000,000 hour base, and would anyone report it there?', '["388.158576; the engine computes it, and nobody reports a recordable rate on that base.", "0.776317 again, since the FAR base is reserved for fatalities and the engine keeps the old base.", "3.881586, since the engine converts any recordable rate to the IOGP base before using a larger one.", "A refusal, since only `fatalAccidentRate` accepts the 100,000,000 base anywhere in this engine."]'::jsonb, 0, '9 x 100,000,000 / 2318640 is 388.158576, which is 500.000000 times the OSHA figure. `incidenceRate` accepts any positive base, so the call succeeds, but a recordable rate belongs on the 200,000 or 1,000,000 base. The engine converts nothing on its own.'),
  ('safetystats', 'beginner', 'final', null, 42, 'A reader sees UGHELLI''s observed FAR of 0.000000 beside IOGP''s 0.769438 for 2024 and concludes UGHELLI is safer than the industry. What is wrong with the conclusion?', '["The two are on different bases, since UGHELLI''s FAR is on the OSHA base and IOGP''s on the FAR base.", "UGHELLI''s zero rests on only 2318640 hours, where a fatality would be rare even at a rate well above the industry''s.", "UGHELLI''s FAR must be computed with the fatal incident count, which would make it nonzero.", "Nothing, since a zero FAR is below any positive FAR."]'::jsonb, 1, 'The zero is correct and says little on its own: IOGP''s 2024 figure rests on 32 fatalities over 4158877000 hours, and a site working a few million hours would expect to see a fatality rarely at the industry''s rate or at several times it. Both FARs are on the fixed 100,000,000 base, and with no fatalities UGHELLI can have had no fatal incident either, so that count cannot move the zero.');
